window.HB_TR["judges"]["ur"]=["1۔ اب یشوع کی موت کے بعد ایسا ہوا کہ بنی اسرائیل نے خداوند سے درخواست کی، کہ، کنعانیوں کے خلاف پہلے ہمارے لیے کون جائے گا تاکہ ان کے خلاف لڑے؟ \n2۔ اور خداوند نے کہا، یہوداہ اوپر جائے گا: دیکھو، میں نے زمین اس کے ہاتھ میں دے دی ہے۔ \n3۔ اور یہوداہ نے اپنے بھائی شمعون سے کہا، میرے ساتھ میری قسمت میں آؤ، تاکہ ہم کنعانیوں کے خلاف لڑیں؛ اور میں بھی تمہارے ساتھ تمہاری قسمت میں جاؤں گا۔ تو شمعون اس کے ساتھ گیا۔ \n4۔ اور یہوداہ اوپر گیا؛ اور خداوند نے کنعانیوں اور پرزیوں کو ان کے ہاتھ میں دے دیا، اور انہوں نے بیزیک میں ان میں سے دس ہزار آدمی مار ڈالے۔ \n5۔ اور انہوں نے بیزک میں آدونبیزیک کو پایا: اور اس کے خلاف لڑے، اور کنعانیوں اور پریزیوں کو قتل کر دیا۔ \n6۔ لیکن آدونبیزیک بھاگ گیا؛ اور وہ اس کا پیچھا کرنے لگے، اسے پکڑ کر اس کے انگوٹھے اور بڑے پیر کاٹ دیے۔ \n7۔ اور ایڈونی بیزیک نے کہا، تیس اور دس بادشاہوں، جن کے انگوٹھے اور بڑے پیر کاٹ دیے گئے، میرے دسترخوان کے نیچے [اپنا گوشت} جمع کر لیا: جیسا کہ میں نے کیا، خدا نے مجھے بدلہ دیا۔ اور وہ اسے یروشلم لے گئے، اور وہاں وہ مر گیا۔ {ان کے انگوٹھے...: عبرانی۔ ان کے ہاتھوں اور پیروں کے انگوٹھے} {جمع کیے گئے: یا، جمع کیے گئے}\n8۔ اب یہوداہ کے بچوں نے یروشلم کے خلاف جنگ کی، اسے قبضے میں لے لیا، تلوار کی نوک سے مارا، اور شہر کو آگ لگا دی۔ \n9۔ اور اس کے بعد یہوداہ کے بچے کنعانیوں کے خلاف لڑنے کے لیے نیچے گئے، جو پہاڑ، جنوب اور وادی میں رہتے تھے۔ {وادی: یا، نچلا علاقہ}\n10۔ اور یہوداہ نے کنعانیوں کے خلاف جو ہیبرون میں بستے تھے: (جو اب ہیبرون کا نام ہے جو پہلے کیرجاتاربا تھا:) اور انہوں نے شیشائی، آہیمان اور تلمائی کو قتل کر دیا۔ \n11۔ اور وہاں سے وہ دیبیر کے باشندوں کے خلاف گیا: اور دیبیر کا نام {تھا} کرجاتسیفر سے پہلے تھا: \n12۔ اور کیلب نے کہا، جو کرجاتھ سیفر کو مارے گا اور اسے لے جائے گا، میں اپنی بیٹی اکسا کو اس کے حوالے کروں گا۔ \n13۔ اور کیلب کے چھوٹے بھائی کیناز کے بیٹے اوثنیئل نے اسے لے لیا: اور اسے اپنی بیٹی اکسا دے دی۔ \n14۔ اور جب وہ اس کے پاس آئی، تو اس نے اسے اپنے والد سے کھیت مانگنے پر مجبور کیا: اور اس نے اپنے گدھے سے آگ لگا دی؛ اور کیلب نے اس سے کہا، تم کیا کرو گی؟ \n15۔ اور اس نے اس سے کہا، مجھے برکت دو: کیونکہ تم نے مجھے جنوبی زمین دی ہے؛ مجھے پانی کے چشمے بھی دے۔ اور کیلب نے اسے اوپر کے چشمے اور نیچے کے چشمے دیے۔ \n16۔ اور موسیٰ کے سسر، کینائٹ کے اولاد، یہوداہ کے بچوں کے ساتھ کھجور کے درختوں کے شہر سے نکل کر یہوداہ کے بیابان میں چلے گئے، جو عراد کے جنوب میں واقع ہے؛ اور وہ لوگوں کے درمیان رہنے لگے۔ \n17۔ اور یہوداہ اپنے بھائی شمعون کے ساتھ گیا، اور انہوں نے کنعانیوں کو مار ڈالا جو زیفتھ میں آباد تھے، اور اسے مکمل طور پر تباہ کر دیا۔ اور شہر کا نام ہورمہ رکھا گیا۔ \n18۔ اسی طرح یہوداہ نے غزہ کو اس کے ساحل کے ساتھ، اسکلون کو اس کے ساحل سے، اور ایکرون نے اس کے ساحل پر قبضہ کیا۔ \n19۔ اور خداوند یہوداہ کے ساتھ تھا؛ اور اس نے {پہاڑ کے باشندوں} کو نکال دیا؛ لیکن وادی کے باشندوں کو نکال نہ سکا، کیونکہ ان کے پاس لوہے کے رتھ تھے۔ {ڈراو...: یا، پہاڑ پر قبضہ کر لیا}\n20۔ اور انہوں نے ہیبرون کو کیلیب کے حوالے کر دیا، جیسا کہ موسیٰ نے کہا: اور اس نے وہاں سے اناک کے تین بیٹوں کو نکال دیا۔ \n21۔ اور بنیامین کے بچوں نے یروشلم میں رہنے والے یبوسی لوگوں کو نہیں نکالا؛ بلکہ یبوسی آج تک یروشلم میں بنیامین کے بچوں کے ساتھ رہتے ہیں۔ \n22۔ اور یوسف خاندان نے بھی بیت ال کے خلاف جنگ کی: اور خداوند ان کے ساتھ تھا۔ \n23۔ اور یوسف کے گھرانے نے بیت ایل کو بیان کرنے بھیجا۔ (اب شہر کا نام {تھا} لوز سے پہلے ہے۔)\n24۔ اور جاسوسوں نے دیکھا کہ ایک آدمی شہر سے باہر آیا، اور اس سے کہا، ہمیں دکھاؤ، ہم تم سے دعا کرتے ہیں کہ تم شہر میں داخل ہو جاؤ، اور ہم تم پر رحم کریں گے۔ \n25۔ اور جب اس نے انہیں شہر میں داخلے کا راستہ دکھایا، تو انہوں نے تلوار کی نوک سے شہر کو مارا؛ لیکن انہوں نے اس آدمی اور اس کے تمام خاندان کو چھوڑ دیا۔ \n26۔ اور وہ آدمی حتیوں کی سرزمین میں گیا، ایک شہر بنایا، اور اس کا نام لوز رکھا: جو آج تک اسی نام پر ہے۔ \n27۔ نہ منسی نے بیت شیان اور اس کے قصبوں کے باشندوں کو، نہ طعناخ اور اس کے قصبوں کو، نہ دور اور اس کے قصبوں کے باشندوں، نہ ایبلام اور اس کے شہروں کے باشندے، نہ میگیدو اور اس کے شہروں کے باشندوں کو نکالا، بلکہ کنعانی اس سرزمین میں بسنے کو تیار تھے۔ \n28۔ اور جب اسرائیل طاقتور تھا، تو انہوں نے کنعانیوں کو خراج دینے پر مجبور کیا، اور انہیں مکمل طور پر نکال باہر نہیں کیا۔ \n29۔ نہ ہی افرائیم نے کنعانیوں کو جو گزر میں بستے تھے، نکال باہر کیا؛ لیکن کنعانیوں نے ان میں سے گززر میں بسے۔ \n30۔ نہ زبولون نے کیترون کے باشندوں کو نکالا، نہ ہی نہالول کے باشندوں کو؛ لیکن کنعانیوں ان کے درمیان رہتے تھے اور خراجی بن گئے۔ \n31. نہ آشر نے آخو کے باشندوں کو، نہ زیدون کے باشندوں، نہ اہلب کے، نہ اخزیب، نہ حلبہ کے، نہ آفک کے، نہ ریحوب کے باشندوں کو نکالا: \n32۔ لیکن اشریائی کنعانیوں کے درمیان رہتے تھے، جو اس سرزمین کے باشندے تھے: کیونکہ انہوں نے انہیں نکالا نہیں۔ \n33۔ نہ نفتالی نے بیت شمش کے باشندوں کو نکالا، نہ ہی بیت ثانات کے باشندوں کو؛ بلکہ وہ کنعانیوں کے درمیان رہتا تھا، جو اس سرزمین کے باشندے تھے؛ تاہم بیت شمش اور بیت ناتھ کے باشندے ان کے باج گزار بن گئے۔ \n34۔ اور اموریوں نے دان کے بچوں کو پہاڑ میں زبردستی بھیج دیا، کیونکہ وہ انہیں وادی میں اترنے نہیں دینا چاہتے تھے: \n35. لیکن اموریوں نے ایجالون کے ہیرس پہاڑ اور شعلبیم میں قیام کیا: پھر بھی یوسف خاندان کا ہاتھ غالب آیا، یہاں تک کہ وہ خراج گزار بن گئے۔ {غالب ہوا: عبرانی۔ بھاری تھا}\n36. اور اموری کا ساحل {تھا} سے اکربم تک چڑھنے سے، چٹان سے، اور اوپر کی طرف۔ {جانے والا...: یا، معلیحاربم}","1۔ اور خداوند کا ایک فرشتہ گلگل سے بوخیم کے پاس آیا، اور کہا، میں نے تمہیں مصر سے باہر نکالا ہے، اور تمہیں اس زمین پر لے آیا ہے جس کی میں نے تمہارے باپ اجداد سے قسم کھائی ہے؛ اور میں نے کہا، میں کبھی تم سے اپنا عہد نہیں توڑوں گا۔ {فرشتہ: یا، پیغامبر}\n2۔ اور تم اس زمین کے باشندوں سے اتحاد نہیں کرو گے؛ تم ان کے قربان گاہیں پھینکو گے: لیکن تم نے میری آواز نہیں مانی: تم نے یہ کیوں کیا؟ \n3۔ اسی لیے میں نے یہ بھی کہا، میں انہیں تمہارے سامنے سے نہیں نکالوں گا؛ بلکہ وہ تمہارے پہلو میں کانٹے کی طرح ہوں گے، اور ان کے خدا تمہارے لیے جال ہوں گے۔ \n4۔ اور جب خداوند کے فرشتے نے یہ الفاظ سب بنی اسرائیل سے کہے، تو لوگوں نے اپنی آواز بلند کی اور رونے لگے۔ \n5۔ اور انہوں نے اس جگہ کا نام بوخیم رکھا: اور وہاں خداوند کے لیے قربانی دی۔ {بوخیم: یعنی، رونے والے}\n6۔ اور جب یشوع نے لوگوں کو جانے دیا، تو بنی اسرائیل نے ہر آدمی کو اس کی وراثت کے لیے زمین پر قبضہ کرنے کے لیے بھیج دیا۔ \n7۔ اور لوگوں نے خداوند کی خدمت یشوع کے تمام دنوں میں کی، اور ان بزرگوں کے تمام دنوں کی جو یشوع سے زیادہ زندہ رہے، جنہوں نے خداوند کے عظیم اعمال دیکھے، جو اس نے اسرائیل کے لیے کیے۔ {زندہ رہا: عبرانی۔ طویل دنوں کے بعد}\n8۔ اور یوشع، نون کا بیٹا، خداوند کا بندہ، فوت ہو گیا، {100 سال} کی عمر میں۔ \n9۔ اور انہوں نے اسے اس کی وراثت کی سرحد پر تیمناتھیرس میں، افرائیم کے پہاڑ میں، پہاڑ گاش کے شمالی جانب دفن کیا۔ {تیمناتھاریس: جسے تیمناتھسراہ بھی کہا جاتا ہے}\n10۔ اور وہ تمام نسلیں اپنے باپ اپ کے پاس جمع ہوئیں: اور ان کے بعد ایک اور نسل پیدا ہوئی، جو نہ تو خداوند کو جانتی تھی، نہ ہی وہ کام جو اس نے اسرائیل کے لیے کیے تھے۔ \n11۔ اور بنی اسرائیل نے خداوند کے سامنے برا کیا اور بعلیم کی خدمت کی: \n12۔ اور انہوں نے اپنے آباؤ اجداد کے خداوند خدا کو چھوڑ دیا، جس نے انہیں مصر کی سرزمین سے نکالا، اور دوسرے دیوتاؤں کی پیروی کی، جو ان لوگوں کے دیوتاؤں کے تھے جو ان کے ارد گرد تھے، اور ان کے سامنے جھک گئے، اور خداوند کو غصے میں مبتلا کر دیا۔ \n13۔ اور انہوں نے خداوند کو چھوڑ دیا، اور بعل اور اشتاروت کی خدمت کی۔ \n14۔ اور خداوند کا غصہ اسرائیل پر شدید تھا، اور اس نے انہیں بگاڑنے والوں کے ہاتھوں میں دے دیا جنہوں نے انہیں بگاڑ دیا، اور انہیں آس پاس کے دشمنوں کے ہاتھوں میں بیچ دیا، تاکہ وہ اپنے دشمنوں کے سامنے کھڑے نہ رہ سکیں۔ \n15۔ جہاں بھی وہ گئے، خداوند کا ہاتھ ان کے خلاف تھا، جیسا کہ خداوند نے فرمایا تھا، اور جیسا کہ خداوند نے ان سے قسم کھائی تھی: اور وہ بہت پریشان تھے۔ \n16۔ پھر بھی خداوند نے ججوں کو زندہ کیا، جنہوں نے انہیں ان لوگوں کے ہاتھوں سے آزاد کر دیا جنہوں نے انہیں بگاڑ دیا۔ {نجات دی: عبرانی۔ نجات یافتہ}\n17۔ پھر بھی وہ اپنے ججوں کی بات نہیں سنتے، بلکہ دوسرے دیوتاؤں کے پیچھے بدکاری کرتے اور ان کے سامنے سر جھکنے لگے: وہ اپنے آباؤ اجداد کے راستے سے جلدی سے ہٹ گئے، خداوند کے احکامات کی پیروی کرتے ہوئے؛ {لیکن} انہوں نے ایسا نہیں کیا۔ \n18۔ اور جب خداوند نے انہیں ججوں کے طور پر اٹھایا، تو خداوند قاضی کے ساتھ تھا، اور انہیں ان کے دشمنوں کے ہاتھوں سے بچایا، تمام دنوں میں، کیونکہ خداوند نے ان کی کراہوں کی وجہ سے توبہ کی جو انہیں ظلم اور پریشان کرتے تھے۔ \n19۔ اور یہ ہوا، جب قاضی مر گیا، {کہ} وہ واپس آئے، اور اپنے آپ کو اپنے باپ دادا سے زیادہ خراب کیا، دوسرے دیوتاؤں کی پیروی کر کے ان کی خدمت اور ان کے سامنے سجدہ کیا؛ انہوں نے اپنے اعمال اور ضدی راستے سے باز نہیں آیا۔ {خراب ہو گئے...: یا، بگڑے} {رک گئے...: عبرانی ان سے کچھ نہ گرے}\n20۔ اور خداوند کا غصہ اسرائیل پر شدید تھا؛ اور اس نے کہا، کیونکہ اس قوم نے میرے عہد کی خلاف ورزی کی ہے جس کا میں نے ان کے باپ دادا سے حکم دیا تھا، اور میری آواز نہیں سنی؛ \n21۔ میں اب سے ان قوموں میں سے کسی کو بھی نہیں نکالوں گا جو یشوع نے اپنی موت کے بعد چھوڑی تھیں: \n22. تاکہ میں ان کے ذریعے اسرائیل کو ثابت کر سکوں، کہ کیا وہ خداوند کے راستے پر چلنے کے لیے اس میں چلتے ہیں، جیسا کہ ان کے باپ اجداد نے کیا تھا، یا نہیں۔ \n23. لہٰذا خداوند نے ان قوموں کو چھوڑ دیا، بغیر انہیں جلدی نکالے؛ نہ ہی انہیں یشوع کے ہاتھ میں دیا۔ {چھوڑ دیا: یا تکلیف دی}","1۔ اب یہ وہ قومیں ہیں جنہیں خداوند نے اسرائیل کو ان کے ذریعے ثابت کرنے کے لیے چھوڑ دیا، {حتیٰ کہ} اتنی {اسرائیل} جتنی کنعان کی تمام جنگوں کو نہیں جانتی تھیں؛ \n2. صرف اس لیے کہ بنی اسرائیل کی نسلیں جان سکیں، انہیں جنگ سکھا سکیں، کم از کم وہ جو پہلے اس کے بارے میں کچھ نہیں جانتی تھیں؛ \n3۔ {یعنی}، فلسطینیوں کے پانچ سردار، تمام کنعانی، اور سیدونیوں اور حوی جو لبنان کے پہاڑ میں آباد تھے، پہاڑ بعلحرمون سے لے کر حمات کے داخلے تک۔ \n4۔ اور انہیں اسرائیل کو ان کے ذریعے ثابت کرنا تھا، یہ جاننے کے لیے کہ کیا وہ خداوند کے احکامات سنیں گے، جو اس نے موسیٰ کے ہاتھوں ان کے آباؤ اجداد کو حکم دیا تھا۔ \n5۔ اور بنی اسرائیل کنعانیوں، حتیوں، اموریوں، پریزوں، حویوں، اور یبوسیوں کے درمیان رہتے تھے: \n6۔ اور انہوں نے اپنی بیٹیوں کو اپنی بیویاں بنایا، اپنی بیٹیوں کو دے دی، اور اپنے دیوتاؤں کی خدمت کی۔ \n7۔ اور بنی اسرائیل نے خداوند کے سامنے برائی کی، اور اپنے خدا کو بھول گئے، اور بعلیم اور جنگلوں کی خدمت کی۔ \n8۔ اسی لیے خداوند کا غصہ اسرائیل پر شدید تھا، اور اس نے انہیں میسوپوٹیمیا کے بادشاہ چوشانریشتھائم کے ہاتھ میں بیچ دیا: اور بنی اسرائیل نے آٹھ سال چوشانریشتھائم کی خدمت کی۔ {میسوپوٹیمیا: عبرانی۔ آرامناہارائم}\n9۔ اور جب بنی اسرائیل نے خداوند سے پکارا، تو خداوند نے بنی اسرائیل کے لیے نجات دہندہ کو اٹھایا، جس نے انہیں نجات دی، {حتیٰ کہ} اوثنیئل، کیناز کا بیٹا، کیلب کا چھوٹا بھائی۔ {نجات دہندہ: عبرانی۔ نجات دہندہ}\n10۔ اور خداوند کی روح اس پر آئی، اس نے اسرائیل کا فیصلہ کیا، اور جنگ کے لیے روانہ ہوا: اور خداوند نے میسوپوٹیمیا کے بادشاہ چوشانریشتھائم کو اپنے ہاتھ میں دے دیا؛ اور اس کا ہاتھ چوشانریشتھائم پر غالب آ گیا۔ {آیا: عبرانی۔ تھا} {میسوپوٹیمیا: عبرانی۔ آرام}\n11۔ اور زمین کو چالیس سال آرام ملا۔ اور عثنیئل، کِناز کا بیٹا، فوت ہو گیا۔ \n12۔ اور بنی اسرائیل نے خداوند کے سامنے پھر سے برائی کی: اور خداوند نے موآب کے بادشاہ ایگلون کو اسرائیل کے خلاف مضبوط کیا، کیونکہ انہوں نے خداوند کے سامنے برائی کی تھی۔ \n13۔ اور اس نے آمون اور عمالیق کے بچوں کو اپنے پاس جمع کیا، اور جا کر اسرائیل کو شکست دی اور کھجور کے درختوں کے شہر پر قبضہ کر لیا۔ \n14۔ یوں بنی اسرائیل نے موآب کے بادشاہ ایگلون کی اٹھارہ سال خدمت کی۔ \n15۔ لیکن جب بنی اسرائیل نے خداوند سے پکارا، تو خداوند نے انہیں ایک نجات دہندہ اٹھایا، ایہود جو جیرا کا بیٹا تھا، جو بنیمی تھا، ایک بائیں ہاتھ کا آدمی تھا، اور اس کے ذریعے بنی اسرائیل نے موآب کے بادشاہ ایگلون کو تحفہ بھیجا۔ {ایک بنیمی: یا، یمنی کا بیٹا} {بائیں ہاتھ سے: عبرانی۔ اپنے دائیں ہاتھ سے بند}\n16۔ لیکن ایہود نے اس کے لیے ایک خنجر بنایا جس کے دو کنارے تھے، جو ایک کیوبٹ لمبا تھا؛ اور اس نے اسے اپنے لباس کے نیچے اپنی دائیں ران پر باندھا۔ \n17۔ اور اس نے تحفہ موآب کے بادشاہ ایگلون کے پاس لایا: اور ایگلون بہت موٹا آدمی تھا۔ \n18۔ اور جب اس نے تحفہ پیش کرنے کا ارادہ کیا، تو اس نے ان لوگوں کو بھیج دیا جو تحفہ رکھتے تھے۔ \n19۔ لیکن وہ خود گلگل کی کانوں سے منہ موڑ گیا اور کہا، اے بادشاہ، میرے پاس تمہارے لیے ایک خفیہ کام ہے: جس نے کہا، خاموش رہو۔ اور جو کچھ اس کے ساتھ کھڑا تھا وہ اس سے نکل گیا۔ {کانیں: یا، کندہ شدہ تصویریں}\n20۔ اور ایہود اس کے پاس آیا؛ اور وہ ایک گرمیوں کے ڈرائنگ روم میں بیٹھا تھا، جو اس کے لیے اکیلا تھا۔ اور ایہود نے کہا، میرے پاس خدا کی طرف سے تمہارے لیے ایک پیغام ہے۔ اور وہ اپنی نشست سے اٹھا۔ {ایک گرمیوں میں...: عبرانی۔ ٹھنڈک کا ایک پارلر}\n21۔ اور ایہود نے اپنا بایاں ہاتھ آگے بڑھایا، دائیں ران سے خنجر نکالا اور اپنے پیٹ میں گھونپ دیا: \n22۔ اور ہاف بھی تلوار کے بعد اندر گیا؛ اور چربی تلوار پر بند ہو گئی، تاکہ وہ خنجر اپنے پیٹ سے نہ نکال سکے؛ اور مٹی باہر نکلی۔ {مٹی...: یا، وہ کولہوں سے باہر نکلی}\n23۔ پھر ایہود برآمدے سے باہر آیا، اور پارلر کے دروازے بند کر دیے اور انہیں بند کر دیا۔ \n24۔ جب وہ باہر گیا، اس کے خادم آئے؛ اور جب انہوں نے دیکھا کہ پارلر کے دروازے بند ہیں، تو انہوں نے کہا، یقینا وہ اپنے گرمیوں کے کمرے میں اپنے پاؤں ڈھانپتا ہے۔ {چھپتا ہے...: یا، اس کا ایزمنٹ کرتا ہے}\n25۔ اور وہ تب تک رکے رہے جب تک شرمندہ نہ ہو گئے: اور دیکھتے ہی اس نے ڈرائنگ روم کے دروازے نہیں کھولے؛ لہٰذا انہوں نے چابی لی، اور انہیں کھولا: اور دیکھتے ہی ان کا رب زمین پر مردہ پڑا۔ \n26۔ اور ایہود ان کے قیام کے دوران فرار ہو گیا، اور کانوں سے آگے نکل کر سیراث کی طرف بھاگ گیا۔ \n27۔ اور جب وہ آیا تو اس نے افرائیم کے پہاڑ میں بگل بجایا، اور بنی اسرائیل اس کے ساتھ پہاڑ سے نیچے اترے اور وہ ان کے سامنے آیا۔ \n28۔ اور اس نے ان سے کہا، میرے پیچھے آؤ، کیونکہ خداوند نے تمہارے دشمنوں موآبیوں کو تمہارے ہاتھ میں دے دیا ہے۔ اور وہ اس کے پیچھے اترے، اور اردن کے راستے موآب کی طرف لے گئے، اور کسی کو بھی گزرنے نہیں دیا۔ \n29۔ اور اس وقت انہوں نے موآب کے تقریبا دس ہزار آدمیوں کو قتل کیا، سب ہوس رکھنے والے اور سب بہادر آدمی؛ اور وہاں کوئی بھی بچ نہ سکا۔ {lusty: Heb. Fat}\n30۔ تو موآب اس دن اسرائیل کے ہاتھوں زیر ہو گیا۔ اور زمین کو چالیس سال آرام ملا۔ \n31۔ اور اس کے بعد شمگار، انات کا بیٹا تھا، جس نے فلستیوں کو چھ سو آدمیوں کو بیل کی لاٹھی سے مار ڈالا، اور اس نے اسرائیل کو بھی بچایا۔","1۔ اور جب ایہود مر گیا تو بنی اسرائیل نے پھر سے خداوند کے سامنے برا کیا۔ \n2۔ اور خداوند نے انہیں کنعان کے بادشاہ یابین کے ہاتھ میں بیچ دیا، جو حزور میں حکمرانی کرتا تھا؛ جس کے لشکر کا کپتان سسرا تھا، جو غیر یہودیوں کے ہاروشیت میں رہتا تھا۔ \n3۔ اور بنی اسرائیل نے خداوند سے پکارا: کیونکہ اس کے پاس نو سو لوہے کی رتھ تھیں؛ اور بیس سال تک اس نے بنی اسرائیل پر ظلم کیا۔ \n4۔ اور دبورہ، ایک نبی، لاپدوتھ کی بیوی، اس وقت اسرائیل کا فیصلہ کرتی تھی۔ \n5۔ اور وہ دبورہ کے کھجور کے درخت کے نیچے، رامہ اور بیت ایل کے درمیان، کوہ افرائیم میں رہی: اور بنی اسرائیل اس کے پاس انصاف کے لیے آئے۔ \n6۔ اور اس نے ابینوعام کے بیٹے باراک کو قدیشنفتالی سے بلایا اور کہا، کیا اسرائیل کے خداوند نے حکم نہیں دیا کہ جاؤ اور تیبر پہاڑ کی طرف بڑھو، اور اپنے ساتھ نفتالی کے بچوں اور زبولون کے بچوں کے دس ہزار آدمی لے جاؤ؟ \n7۔ اور میں یابین کی فوج کے کپتان کیشون سیسرا کو اس کے رتھ اور ہجوم کے ساتھ دریا کی طرف کھینچوں گا؛ اور میں اسے تمہارے ہاتھ میں چھوڑوں گا۔ \n8۔ اور باراک نے اس سے کہا، اگر تم میرے ساتھ جانا چاہتی ہو تو میں جاؤں گا: لیکن اگر تم میرے ساتھ نہیں جاؤ گی، تو میں نہیں جاؤں گا۔ \n9۔ اور اس نے کہا، میں ضرور تمہارے ساتھ جاؤں گی: چاہے تم جو سفر کرو وہ تمہاری عزت کے لیے نہ ہو؛ کیونکہ خداوند سسیرا کو ایک عورت کے ہاتھ میں بیچ دے گا۔ اور دبورہ اٹھی، اور باراک کے ساتھ قدیش چلی گئی۔ \n10۔ اور باراک نے زبولون اور نفتالی کو قدیش کے پاس بلایا؛ اور وہ دس ہزار آدمیوں کے ساتھ اپنے قدموں میں چڑھا: اور دبورہ اس کے ساتھ چڑھ گئی۔ \n11۔ اب ہیبر کینی، جو موسیٰ کے سسر ہوباب کے بچوں میں سے تھا، نے خود کو کینیوں سے الگ کر لیا تھا، اور زعنیم کے میدان میں خیمہ لگا دیا، جو قدیش کے قریب ہے۔ \n12۔ اور انہوں نے سیسرا کو دکھایا کہ ابینوام کا بیٹا باراک تابور پر چڑھ گیا ہے۔ \n13۔ اور سسیرا نے اپنی تمام رتھ جمع کیں، {حتیٰ کہ} نو سو لوہے کی رتھیں، اور تمام لوگ جو اس کے ساتھ تھے، غیر قوموں کے ہاروشیت سے لے کر کیشون کے دریا تک۔ {مل کر: عبرانی۔ فریاد کے ذریعے، یا، اعلان کے ذریعے}\n14. اور دبورہ نے باراک سے کہا، اوپر؛ کیونکہ یہ وہ دن ہے جب خداوند نے سسیرا کو تمہارے ہاتھ میں دیا ہے: کیا خداوند تمہارے سامنے نہیں گیا؟ تو باراک تیبر پہاڑ سے نیچے اترا، اور اس کے پیچھے دس ہزار آدمی۔ \n15۔ اور خداوند نے سیسرہ کو، اور اس کی تمام رتھوں اور اس کے تمام لشکر کو تلوار کے نوک سے باراک کے سامنے بے چین کر دیا؛ تاکہ سیسیرا نے اپنی رتھ کو روشن کیا اور اپنے قدموں پر بھاگ گیا۔ \n16۔ لیکن باراک رتھوں کے پیچھے گیا، اور لشکر کے پیچھے غیر یہودیوں کے ہاروشیت کی طرف: اور سسیرا کی ساری فوج تلوار کے کنارے پر گر گئی؛ {اور} کوئی آدمی باقی نہ رہا۔ {ایک آدمی: عبرانی۔ ایک کے لیے}\n17۔ تاہم سسیرا اپنے پیروں پر بھاگ کر ہیبر دی کینائٹ کی بیوی یائل کے خیمے کی طرف بھاگ گیا: کیونکہ حزور کے بادشاہ یابین اور حبر کینی خاندان کے درمیان امن قائم تھا۔ \n18۔ اور یائل سسرہ سے ملنے باہر گیا، اور اس سے کہا، میرے رب، میرے پاس مڑ جاؤ؛ ڈر مت۔ اور جب وہ خیمے میں اس کے پاس آیا، تو اس نے اسے چادر میں ڈھانپ دیا۔ {چادر: یا، قالین یا، کمبل}\n19۔ اور اس نے اس سے کہا، مجھے تھوڑا سا پانی دو، میں تم سے درخواست کرتا ہوں؛ کیونکہ مجھے پیاس لگی ہے۔ اور اس نے دودھ کی بوتل کھولی، اسے پانی دیا، اور اسے ڈھانپ دیا۔ \n20۔ پھر اس نے اس سے کہا، خیمے کے دروازے پر کھڑے ہو جاؤ، اور جب کوئی آدمی آئے گا اور تم سے پوچھے گا، کیا یہاں کوئی آدمی ہے؟ کہ تم کہو گے، نہیں۔ \n21۔ پھر یائل ہیبر کی بیوی نے خیمے کا کیل لیا، ہاتھ میں ہتھوڑا لیا، اور نرمی سے اس کے پاس گئی، کیل اس کے کنپٹیوں میں گھونپ دی اور زمین میں لگا دی: کیونکہ وہ گہری نیند میں تھا اور تھکا ہوا تھا۔ تو وہ مر گیا۔ {اور لیا: عبرانی۔ اور رکھا}\n22۔ اور دیکھو، جب باراک سسرہ کا پیچھا کر رہا تھا، یائل اس سے ملنے باہر آیا اور اس سے کہا، آؤ، اور میں تمہیں وہ آدمی دکھاؤں گا جسے تم تلاش کر رہے ہو۔ اور جب وہ اس کے خیمے میں آیا، تو دیکھو، سسرہ مردہ پڑی تھی، اور کیل اس کے کنپٹیوں میں ٹھنسا ہوا تھا۔ \n23۔ یوں خدا نے اس دن کنعان کے بادشاہ یابین کو بنی اسرائیل کے سامنے زیر کر دیا۔ \n24۔ اور بنی اسرائیل کا ہاتھ کامیاب ہوا، اور کنعان کے بادشاہ یابین پر غالب آئے، یہاں تک کہ انہوں نے کنعان کے بادشاہ یابین کو تباہ کر دیا۔ {خوشحال...: عبرانی۔ جانا مشکل تھا}","1۔ پھر اس دن دبورہ اور ابینعام کے بیٹے باراک نے گایا، اور کہا، \n2. خداوند کی تعریف کرو کہ اس نے اسرائیل کا انتقام لیا، جب لوگوں نے اپنی مرضی سے خود کو قربان کیا۔ \n3. سنو، اے بادشاہو؛ سنو، اے شہزادوں؛ میں، {حتی} میں، خداوند کے لیے گاؤں گا؛ میں اسرائیل کے خداوند خدا کی {تعریف} گاؤں گا۔ \n4۔ اے خداوند، جب تو سعیر سے نکلے، جب تم ایڈوم کے میدان سے نکلے، زمین لرز گئی، آسمان گر گئے، بادل بھی پانی گرا دیے۔ \n5۔ پہاڑ خداوند کے سامنے سے پگھل گئے، {حتیٰ کہ} وہ سینا جو رب خدا اسرائیل کے سامنے تھا۔ {پگھلا ہوا: عبرانی۔ بہا}\n6۔ شمگار بیٹے انات کے زمانے میں، یائل کے زمانے میں، شاہراہیں خالی تھیں، اور مسافر ضمنی راستوں سے گزرتے تھے۔ {مسافر: عبرانی۔ راستوں پر چلنے والے} {بائی وے: عبری۔ ٹیڑھی راہیں}\n7. {گاؤں کے باشندے} بند ہو گئے، وہ اسرائیل میں بند ہو گئے، یہاں تک کہ میں نے دبورہ کی پیدائش کی، اور میں اسرائیل میں ایک ماں پیدا ہوئی۔ \n8۔ انہوں نے نئے خدا چنے؛ پھر کیا دروازوں میں جنگ تھی: کیا اسرائیل میں چالیس ہزار میں کوئی ڈھال یا نیزہ نظر آیا؟ \n9. میرا دل اسرائیل کے حکمرانوں کی طرف ہے، جنہوں نے عوام کے درمیان خود کو خوش دلی سے پیش کیا۔ خداوند کو برکت دے۔ \n10. بولو، اے جو سفید گدھوں پر سوار ہو، جو فیصلہ کرتے ہیں، اور راستے میں چلتے ہو۔ {بولو: یا، مراقبہ کرو}\n11۔ {جو لوگ تیر اندازوں کے شور سے بچائے جاتے ہیں} پانی نکالنے کی جگہوں پر، وہاں وہ خداوند کے نیک اعمال دہرائیں گے، {حتیٰ کہ} وہ نیک اعمال {حتیٰ کہ} اسرائیل کے گاؤں کے باشندوں کے ساتھ: پھر خداوند کے لوگ دروازوں تک جائیں گے۔ {راستباز...: عبرانی راستبازی}\n12. جاگو، جاگو، دبورا: جاگو، جاگو، ایک گیت پڑھو: اٹھو، باراک، اور اپنی قید کو قید کرو، اے ابینوام کے بیٹے۔ \n13۔ پھر اس نے جو باقی رہ گیا اسے لوگوں کے اشرافیہ پر حکمرانی دی ہے: خداوند نے مجھے طاقتوروں پر حکمرانی دی۔ \n14۔ افرائیم سے {تھا} ان کی جڑ عمالیق کے خلاف تھی؛ تیرے بعد، بنیمن، تمہارے لوگوں میں؛ مخیر سے حکمران نیچے آئے، اور زبولون سے وہ لوگ جو لکھنے والے کا قلم سنبھالتے ہیں۔ {ہینڈل: عبرانی۔ نکالیں}\n15۔ اور اسکھار کے شہزادے {تھے} دبورہ کے ساتھ؛ یہاں تک کہ اسکھار بھی، اور باراک بھی: اسے پیدل وادی میں بھیجا گیا۔ روبن کی تقسیم {کیونکہ وہاں دل کے بڑے خیالات تھے۔ {پاؤں: عبرانی۔ اس کے قدم} {خیالات: عبرانی۔ تاثرات} {لیے: یا، ان}\n16. تم بھیڑوں کے جھنڈوں میں کیوں بیٹھ رہے ہو، تاکہ ریوڑوں کی آوازیں سن سکیں؟ کیونکہ روبن کی تقسیم {دل کی بڑی تلاش تھی}۔ {For: or, In}\n17۔ گلعاد اردن کے پار رہا: اور دان جہازوں میں کیوں رہا؟ آشر سمندر کے کنارے پر رہا، اور اپنی دراڑوں میں رہا۔ {ساحل: یا، بندرگاہ} {دراڑیں: یا، ندی نالیں}\n18۔ زبولون اور نفتالی {تھے} ایک ایسی قوم {جن} نے میدان کے بلند مقامات پر اپنی جانوں کو موت تک خطرے میں ڈالا۔ {خطرے میں ڈالا ہوا: عبرانی۔ ملامت کے سامنے آئے}\n19۔ بادشاہ آئے اور کنعان کے بادشاہوں سے تانخ میں میگیدو کے پانیوں کے کنارے لڑے؛ انہیں کوئی پیسے کا فائدہ نہیں ہوا۔ \n20۔ انہوں نے آسمان سے لڑائی کی؛ ستاروں نے اپنے راستوں میں سسیرا کے خلاف لڑائی کی۔ {کورسز: عبرانی راستے}\n21. کیشون کے دریا نے انہیں بہا لیا، وہ قدیم دریا، دریا کیشون۔ اے میری جان، تو نے طاقت کو روند دیا۔ \n22. پھر گھوڑے کے گھوڑوں کے گھوڑوں کو ان کے طاقتور گھوڑوں کے ذریعے توڑ دیا گیا۔ {پرانسنگز: یا، پاؤں چلنا، یا، چھلکیاں}\n23. خداوند کے فرشتے نے فرمایا، میروز پر لعنت، اور اس کے باشندوں پر سخت لعنت؛ کیونکہ وہ خداوند کی مدد کو نہیں آئے، نہ ہی خداوند کی مدد کو طاقتوروں کے خلاف۔ \n24۔ عورتوں پر مبارک ہو، یائل، ہیبر کینی کی بیوی، مبارک ہو، وہ خیمے میں عورتوں سے اوپر ہو۔ \n25۔ اس نے پانی مانگا، {اور} اس نے {اسے} دودھ دیا؛ اس نے ایک شاہانہ برتن میں مکھن نکالا۔ \n26۔ اس نے اپنا ہاتھ کیل پر رکھا، اور اپنا دایاں ہاتھ مزدوروں کے ہتھوڑے پر؛ اور ہتھوڑے سے اس نے سسرہ کو مارا اور اس کے سر کو مارا جب اس نے اس کے کنپٹیوں کو چھید کر مارا۔ {ساتھ...: عبرانی اس نے ہتھوڑا مارا}\n27۔ اس کے قدموں میں وہ جھکا، وہ گرا، وہ لیٹ گیا: اس کے قدموں میں جھکا، وہ گرا: جہاں اس نے سر جھکا، وہاں وہ مردہ گر گیا۔ {پر: عبرانی۔ درمیان} {مردہ: عبرانی۔ تباہ ہو گیا}\n28۔ سسیرا کی ماں نے کھڑکی کی طرف دیکھا، اور جالی کے ذریعے پکارا، اس کی رتھ اتنی دیر کیوں آ رہی ہے؟ اپنے رتھ کے پہیے کیوں روکے؟ \n29۔ اس کی عقلمند خواتین نے جواب دیا، ہاں، اس نے اپنے آپ کو جواب دیا، {جواب: عبرانی۔ اس کے الفاظ}\n30۔ کیا انہوں نے شکار کو تقسیم نہیں کیا؟ کیا انہوں نے شکار کو تقسیم نہیں کیا؛ ہر آدمی کو ایک دوشیزہ {یا} دو؛ سسیرا کے لیے مختلف رنگوں کا شکار، مختلف رنگوں کے سلائی کے شکار، دونوں طرف مختلف رنگوں کے سلائی کے شکار، {ملتے ہیں} ان کی گردن کے لیے جو لوٹ لوٹ لیتے ہیں؟ {ہر...: عبرانی۔ ایک آدمی کا سر}\n31۔ تو اے خداوند، تیرے تمام دشمن مر جائیں، بلکہ جو لوگ اس سے محبت کرتے ہیں وہ سورج کی طرح ہوں جب وہ اپنی طاقت میں باہر نکلے۔ اور زمین کو چالیس سال آرام ملا۔","1۔ اور بنی اسرائیل نے خداوند کے سامنے برائی کی: اور خداوند نے انہیں سات سال مدیان کے ہاتھ میں دے دیا۔ \n2۔ اور مدیان کا ہاتھ اسرائیل پر غالب آیا: {اور} مدیانیوں کی وجہ سے بنی اسرائیل نے انہیں وہ غاریں بنائیں جو پہاڑوں، غاروں اور قلعوں میں ہیں۔ {غالب ہوا: عبرانی۔ مضبوط تھا}\n3۔ اور {یوں} جب اسرائیل نے بیج بوئے، مدیانی اوپر آئے، اور عمالقیوں اور مشرق کے بچے بھی ان کے خلاف آ گئے؛ \n4۔ اور انہوں نے ان کے خلاف خیمہ لگایا، اور زمین کے پھیلاؤ کو تباہ کر دیا، یہاں تک کہ تم غزہ آ گئے، اور اسرائیل کے لیے کوئی خوراک نہ چھوڑی، نہ بھیڑ، نہ بیل، نہ گدھ۔ {بھیڑ: یا بکری}\n5۔ کیونکہ وہ اپنے مویشی اور خیمے لے کر آئے اور کثرت کے لیے ٹڈوں کی طرح آئے؛ کیونکہ وہ اور ان کے اونٹ بے شمار تھے: اور وہ زمین میں داخل ہوئے تاکہ اسے تباہ کر سکیں۔ \n6۔ اور اسرائیل مدیانیوں کی وجہ سے بہت غریب ہو گیا؛ اور بنی اسرائیل نے خداوند سے پکارا۔ \n7۔ اور ایسا ہوا، جب بنی اسرائیل نے مدیانیوں کی وجہ سے خداوند سے پکارا، \n8۔ کہ خداوند نے بنی اسرائیل کے پاس ایک نبی بھیجا، جس نے ان سے کہا، یوں اسرائیل کے خداوند نے فرمایا، میں نے تمہیں مصر سے اٹھایا اور تمہیں غلامی کے گھر سے نکالا؛ {ایک نبی: عبرانی۔ ایک آدمی نبی ہے}\n9۔ اور میں نے تمہیں مصریوں کے ہاتھوں سے اور ان سب کے ہاتھوں سے نکالا جو تم پر ظلم کر رہے تھے، اور انہیں تمہارے سامنے سے نکال دیا، اور تمہیں ان کی زمین دی؛ \n10۔ اور میں نے تم سے کہا، میں خداوند تمہارا خدا ہوں؛ اموریوں کے دیوتاؤں سے مت ڈرو، جن کی سرزمین میں تم رہتے ہو، لیکن تم نے میری آواز نہیں مانی۔ \n11۔ اور خداوند کا ایک فرشتہ آیا، اور ایک بلوط کے درخت کے نیچے بیٹھا جو {تھا} اوفرہ میں، جو {تھا} یوآش ابیزریت سے متعلق تھا: اور اس کا بیٹا گدعون گندم کو شراب کے پریس کے پاس کاٹتا تھا، تاکہ اسے مدیانیوں سے چھپایا جا سکے۔ {گیدئون: گر. گدعون} {چھپانے کے لیے...: عبرانی۔ اسے بھاگنے کے لیے}\n12۔ اور خداوند کا فرشتہ اس کے سامنے ظاہر ہوا اور کہا، خداوند تمہارے ساتھ ہے، اے عظیم بہادر انسان۔ \n13۔ اور گیدعون نے اس سے کہا، اے میرے خداوند، اگر خداوند ہمارے ساتھ ہے تو پھر یہ سب ہمارے ساتھ کیوں ہوا؟ اور اس کے تمام معجزات کہاں ہیں جن کے بارے میں ہمارے آباؤ اجداد نے ہمیں بتایا تھا، کہہ رہے تھے، کیا خداوند نے ہمیں مصر سے نہیں اٹھایا؟ لیکن اب خداوند نے ہمیں چھوڑ دیا ہے، اور مدیانی لوگوں کے حوالے کر دیا ہے۔ \n14۔ اور خداوند نے اسے دیکھا اور کہا، اپنی طاقت میں جاؤ، اور تم اسرائیل کو مدیانیوں کے ہاتھوں سے بچاؤ گے: کیا میں نے تمہیں نہیں بھیجا؟ \n15۔ اور اس نے اس سے کہا، اے میرے خداوند، میں اسرائیل کو کس طرح بچاؤں؟ دیکھو، میرا خاندان مناسی میں غریب ہے، اور میں اپنے والد کے گھر میں سب سے کم ہوں۔ {میرا خاندان...: عبرانی۔ میرا ہزار سب سے کمتر ہے}\n16۔ اور خداوند نے اسے فرمایا، یقینا میں تیرے ساتھ ہوں گا، اور تو مدیانی لوگوں کو ایک ہی آدمی کی طرح مارے گا۔ \n17۔ اور اس نے اس سے کہا، اگر اب میں نے تمہاری نظر میں فضل پایا ہے، تو مجھے کوئی اشارہ دکھاؤ کہ تم مجھ سے بات کر رہے ہو۔ \n18۔ یہاں سے مت جاؤ، میں تم سے دعا کرتا ہوں، جب تک میں تمہارے پاس نہ آؤں، اپنا تحفہ نہ لے آؤں، اور اسے تمہارے سامنے نہ رکھوں۔ اور اس نے کہا، میں رہوں گا جب تک تم دوبارہ نہ آؤ۔ {تحفہ: یا، گوشت کی پیشکش}\n19۔ اور جدعون اندر گیا، اور ایک بچے کو تیار کیا، اور ایک ایفا آٹے کے بغیر خمیر کے کیک تیار کیے: گوشت کو اس نے ایک ٹوکری میں رکھا، اور شوربہ کو ایک برتن میں رکھا، اور اسے بلوط کے نیچے نکالا اور پیش کیا۔ {ایک بچہ: عبرانی۔ بکریوں کا بچہ}\n20۔ اور خدا کے فرشتے نے اس سے کہا، گوشت اور بغیر خمیر کے کیک لے لو، اور انہیں اس چٹان پر رکھ دو، اور شوربہ ڈال دو۔ اور اس نے ایسا ہی کیا۔ \n21۔ پھر خداوند کے فرشتے نے اپنے ہاتھ میں موجود چھڑی کا سرا نکالا، اور گوشت اور بغیر خمیر کے کیک کو چھوا؛ اور وہاں چٹان سے آگ اٹھی، اور گوشت اور بغیر خمیر کے کیک کو جلا دیا۔ پھر خداوند کا فرشتہ اس کی نظر سے اوجھل ہو گیا۔ \n22۔ اور جب جدعون نے محسوس کیا کہ وہ خداوند کا فرشتہ ہے، تو جدعون نے کہا، اے خداوند خدا! کیونکہ میں نے خداوند کے فرشتے کو آمنے سامنے دیکھا ہے۔ \n23۔ اور خداوند نے اسے کہا، تم پر امن ہو؛ ڈر مت: تم نہیں مرو گے۔ \n24۔ پھر گیدعون نے وہاں خداوند کے لیے ایک قربان گاہ بنائی، اور اسے یہوواہشالوم کہا: آج تک یہ ابیعزریٹیوں کی اوفرہ میں ہے۔ {یہوواشالوم: یعنی، خداوند امن بھیجے}\n25۔ اور اسی رات خداوند نے اس سے فرمایا: اپنے والد کا ننھا بیل، جو سات سال کا دوسرا بیل ہے، لے کر اپنے والد کے پاس موجود بعل کا مذبح پھینک دو، اور اس کے پاس موجود جھنڈ کو کاٹ دو: {حتی: یا، اور}\n26۔ اور اس چٹان کی چوٹی پر، ترتیب شدہ جگہ پر، خداوند اپنے خدا کے لیے ایک قربان گاہ تعمیر کرو، اور دوسرا بیل لے کر اس جنگل کی لکڑی سے جلائی ہوئی قربانی پیش کرو جسے تم کاٹنا چاہتے ہو۔ {چٹان: عبرانی مضبوط جگہ} {ترتیب میں...: یا، منظم طریقے سے}\n27۔ پھر گدعون نے اپنے خادموں میں سے دس آدمی لے لیے، اور خداوند کے حکم کے مطابق کیا: اور یہ اس لیے تھا کہ وہ اپنے والد کے گھرانے اور شہر کے لوگوں سے ڈرتا تھا، اس لیے وہ دن میں یہ کام نہیں کر سکتا تھا، اس لیے وہ رات کو ایسا کر رہا تھا۔ \n28۔ اور جب شہر کے لوگ صبح سویرے اٹھے، تو دیکھو، بعل کا قربان گاہ گرا دیا گیا، اور اس نے جو جھنڈ کاٹ دیا تھا، اور دوسرا بیل اس قربان گاہ پر پیش کیا گیا جو بنایا گیا تھا۔ \n29۔ اور انہوں نے ایک دوسرے سے کہا، یہ کام کس نے کیا ہے؟ اور جب انہوں نے پوچھا تو کہا، جدعون جو یوآش کا بیٹا ہے، یہ کام کر چکا ہے۔ \n30۔ پھر شہر کے لوگوں نے یوآش سے کہا، اپنے بیٹے کو نکالو تاکہ وہ مر جائے، کیونکہ اس نے بعل کی قربان گاہ گرا دی ہے، اور اس نے اس جھنڈ کو کاٹ دیا جو اس کے پاس تھا۔ \n31۔ اور یوآش نے ان سب سے کہا جو اس کے خلاف کھڑے تھے، کیا تم بعل کے لیے دعا کرو گے؟ کیا تم اسے بچاؤ گے؟ جو اس کے لیے دعا کرے گا، اسے {ابھی} صبح ہونے تک قتل کر دیا جائے: اگر وہ خدا ہے تو اپنے لیے دعا کرے، کیونکہ {ایک} نے اپنا مذبح گرا دیا ہے۔ \n32۔ اسی لیے اس دن اس نے اسے یروبعل کہا، کہنے دو، بعل اس کے خلاف دعا کرے کیونکہ اس نے اپنا مذبح گرا دیا ہے۔ {یربعل: یعنی، بعل دعا کرے} {یروبیشث: یعنی، شرمناک چیز دعا کرے}\n33۔ پھر تمام مدیانی اور عمالقی اور مشرق کے بچے اکٹھے ہو گئے، اور وادی یزرعیل میں چڑھائے گئے۔ \n34۔ لیکن خداوند کی روح گیدعون پر آئی، اور اس نے بگل بجایا؛ اور ابیزر اس کے پیچھے جمع ہو گیا۔ {آیا...: عبرانی۔ کپڑوں میں} {جمع ہوا: عبرانی۔ بلایا}\n35۔ اور اس نے پورے منسی میں پیغامبر بھیجے؛ جو بھی اس کے پیچھے جمع ہوا؛ اور اس نے آشر، زبولون، اور نفتالی کے لیے پیغامبر بھیجے؛ اور وہ ان سے ملنے آئے۔ {جمع ہوئے: عبرانی۔ بلایا}\n36۔ اور جدعون نے خدا سے کہا، اگر تم میرے ہاتھ سے اسرائیل کو بچاؤ گے، جیسا کہ تم نے کہا ہے، \n37۔ دیکھو، میں اون کی اون فرش پر رکھوں گا؛ {اور} اگر اوس صرف اون پر ہو، اور {وہ زمین کے کنارے} پر خشک ہو جائے، تو میں جان جاؤں گا کہ تم میرے ہاتھ سے اسرائیل کو بچاؤ گے، جیسا کہ تم نے کہا ہے۔ \n38۔ اور ایسا ہی ہوا: کیونکہ وہ کل صبح صبح اٹھ کھڑا ہوا، اون کو جوڑ کر اون سے اوس نکال لیا، پانی سے بھرا پیالہ۔ \n39۔ اور گیدعون نے خدا سے کہا، اپنا غصہ مجھ پر نہ ہو، اور میں صرف اس بار بولوں گا: مجھے ثابت کرنے دو، میں تم سے دعا کرتا ہوں، لیکن اس بار اون کے ساتھ؛ اب یہ صرف اون پر خشک ہو، اور تمام زمین پر اوس ہو۔ \n40۔ اور خدا نے اس رات ایسا ہی کیا: کیونکہ وہ صرف اون پر خشک تھا، اور زمین پر اوس تھا۔","1۔ پھر یروبعل، جو جدعون ہے، اور اس کے ساتھ موجود تمام لوگ صبح سویرے اٹھے اور ہارود کے کنویں کے پاس کھڑے ہو گئے، تاکہ مدیانیوں کا لشکر ان کے شمال کنارے پر، مورہ کی پہاڑی کے پاس، وادی میں کھڑا ہو گیا۔ \n2۔ اور خداوند نے گدعون سے کہا، جو لوگ تیرے ساتھ ہیں وہ میرے لیے مدیانی لوگوں کو ان کے حوالے کرنے کے لیے بہت زیادہ ہیں، ورنہ اسرائیل میرے خلاف فخر کریں گے، اور کہتا ہے، میرا اپنا ہاتھ مجھے بچا چکا ہے۔ \n3۔ اب جاؤ، لوگوں کے کانوں میں اعلان کرو، کہو، جو خوفزدہ اور خوفزدہ ہے، وہ جلدی جلعید پہاڑ سے روانہ ہو جائے۔ اور وہاں قوم میں سے بیس اور دو ہزار واپس آئے؛ اور دس ہزار باقی رہ گئے۔ \n4۔ اور خداوند نے گدعون سے کہا، لوگ ابھی بھی بہت زیادہ ہیں؛ انہیں پانی میں لے آؤ، اور میں وہاں تمہارے لیے آزماؤں گا: اور وہ ہوگا، جس کے بارے میں میں کہوں گا، یہ تمہارے ساتھ جائے گا، وہی تمہارے ساتھ جائے گا؛ اور جس کے بارے میں میں کہوں گا، یہ تمہارے ساتھ نہیں جائے گا، وہ نہیں جائے گا۔ \n5۔ تو اس نے لوگوں کو پانی میں اتارا: اور خداوند نے گیدعون سے کہا، جو بھی اپنی زبان سے پانی کو چٹکائے گا، جیسے کتا ٹپکے، تو اسے اکیلا رکھ دینا؛ اسی طرح ہر وہ شخص جو گھٹنے ٹیک کر پانی پیتا ہے۔ \n6۔ اور جو لوگ چاٹتے رہے، {ہاتھ منہ پر رکھتے} تین سو آدمی تھے: لیکن باقی سب لوگ پانی پینے کے لیے گھٹنوں کے بل جھک گئے۔ \n7۔ اور خداوند نے گدعون سے کہا، تین سو آدمیوں کے ذریعے جو چپکے مارے ہیں، میں تمہیں بچاؤں گا، اور مدیانی لوگوں کو تمہارے ہاتھ میں دوں گا، اور تمام {دوسرے} لوگوں کو ہر ایک کو اس کی جگہ لے جاؤں گا۔ \n8۔ تو لوگوں نے اپنے ہاتھوں میں خوراک اور بگل لیے: اور اس نے باقی سب اسرائیل کو اپنے خیمے میں بھیج دیا، اور ان تین سو آدمیوں کو اپنے پاس رکھا: اور مدیان کی فوج وادی میں اس کے نیچے تھی۔ \n9۔ اور اسی رات ایسا ہوا کہ خداوند نے اسے فرمایا، اٹھو، لشکر کے پاس اتر جاؤ؛ کیونکہ میں نے اسے تیرے ہاتھ میں دے دیا ہے۔ \n10۔ لیکن اگر تم نیچے جانے سے ڈرتے ہو، تو اپنے خادم فورہ کے ساتھ لشکر کے پاس جاؤ: \n11۔ اور تم سنو گے جو وہ کہتے ہیں؛ اور اس کے بعد تمہارے ہاتھ مضبوط کیے جائیں گے تاکہ وہ لشکر کے پاس جا سکیں۔ پھر وہ اپنے خادم فورہ کے ساتھ ان مسلح مردوں کے باہر گیا جو لشکر میں تھے۔ {مسلح مرد: یا، پانچ کی قطار میں}\n12۔ اور مدیانی اور امالیقی اور مشرق کے تمام بچے وادی میں ٹڈوں کی طرح پڑے تھے؛ اور ان کے اونٹ بے شمار تھے، جیسے سمندر کے کنارے ریت کی طرح جو کثرت کے لیے ہو۔ \n13۔ اور جب جدعون آیا، دیکھو، ایک آدمی تھا جس نے اپنے ساتھی کو خواب سنایا، اور کہا، دیکھو، میں نے خواب دیکھا، اور دیکھو، جو کی روٹی کا ایک کیک مدیان کے لشکر میں گرا، اور خیمے کے پاس آیا، اسے مارا کہ وہ گر گیا، اور اسے الٹ دیا، خیمہ بھی پڑا تھا۔ \n14۔ اور اس کے ساتھی نے جواب دیا اور کہا، یہ صرف جدعون، یوآش کے بیٹے کی تلوار ہے، جو اسرائیل کا آدمی تھا: {کیونکہ} خدا نے مدیان اور تمام لشکر کو اس کے ہاتھ میں دے دیا ہے۔ \n15. اور جب گیدئون نے خواب کی کہانی اور اس کی تعبیر سنی، جس کی وہ عبادت کر رہا تھا، تو وہ اسرائیل کے لشکر میں واپس آ گیا اور کہا، اٹھو؛ کیونکہ خداوند نے تمہارے ہاتھ میں مدیان کی فوج دے دی ہے۔ {تشریح: عبرانی۔ ٹوٹنا}\n16۔ اور اس نے تین سو آدمیوں کو تین جماعتوں میں تقسیم کیا، اور ہر آدمی کے ہاتھ میں ایک ترمپٹ رکھا، خالی جگ اور جگوں میں چراغ رکھے۔ {ایک ترمپٹ...: عبرانی۔ سب کے ہاتھ میں ترمپٹ} {چراغ: یا، آگ کے جھلکے، یا مشعل}\n17۔ اور اس نے ان سے کہا، مجھے دیکھو، اور ایسا ہی کرو: اور دیکھو، جب میں کیمپ کے باہر آؤں گا، تو تم بھی ویسا ہی کرو گے۔ \n18۔ جب میں بگل سے بجاؤں، میں اور جو سب میرے ساتھ ہیں، تو تم بھی ہر طرف بگل بجاؤ، اور کہو، {تلوار} خداوند اور جدعون کی۔ \n19۔ تو جدعون، اور اس کے ساتھ سو آدمی جو اس کے ساتھ تھے، درمیانی پہرے کے آغاز میں کیمپ کے باہر آئے؛ اور انہوں نے ابھی حال ہی میں پہرہ لگایا تھا: اور انہوں نے بگل بجائے، اور ان جگوں کو توڑ دیا جو ان کے ہاتھ میں تھے۔ \n20۔ اور تینوں گروہوں نے بگل بجائے، جگوں کو توڑا، اور بائیں ہاتھ میں چراغ اور دائیں ہاتھ میں بگل پکڑے تاکہ بجائیں: اور انہوں نے پکارا، خداوند اور جدعون کی تلوار۔ \n21۔ اور انہوں نے ہر آدمی کو اس کی جگہ کیمپ کے ارد گرد کھڑا کر دیا، اور سب فوج بھاگ گئی، رونے لگی، اور بھاگ گئی۔ \n22۔ اور تین سو نے بگل بجائے، اور خداوند نے ہر آدمی کی تلوار اپنے ساتھی کے خلاف رکھی، حتیٰ کہ پوری لشکر میں: اور لشکر زریرات میں بیت شیتا کی طرف بھاگ گیا، {اور} ابل مہولا کی سرحد تک، تاببت کی طرف۔ {اندر: یا، کی طرف} {سرحد: عبرانی۔ لب}\n23۔ اور اسرائیل کے لوگ نفتالی، آشر، اور پورے منسی سے جمع ہوئے اور مدیانیوں کا پیچھا کرنے لگے۔ \n24۔ اور جدعون نے پورے کوہ افریم میں پیغامبر بھیجے اور کہا، مدیانیوں کے خلاف نیچے آؤ، اور ان کے سامنے بیت بارہ اور اردن کے پانی لے جاؤ۔ پھر افریم کے تمام لوگ اکٹھے ہو گئے اور بیت بارہ اور اردن کے پانی لے گئے۔ \n25۔ اور انہوں نے مدیانیوں کے دو شہزادے، اوریب اور زیب کو پکڑا؛ اوریب کو چٹان پر مار ڈالا، اور زیب کو زیب کے شراب خانے پر مار ڈالا، اور مدیان کا پیچھا کیا، اور اوریب اور زیب کے سر اردن کے دوسری طرف گدعون کے پاس لے آئے۔","1۔ اور افرائیم کے لوگوں نے اس سے کہا، تم نے ہماری خدمت کیوں کی کہ تم نے ہمیں بلایا نہیں، جب تم مدیانیوں سے لڑنے جا رہے تھے؟ اور انہوں نے اس پر سختی سے ڈانٹا تھا۔ {کیوں...: حبری۔ یہ کیا ہے جو تم نے ہمارے ساتھ کیا ہے} {تیز: عبرانی۔ شدید}\n2۔ اور اس نے ان سے کہا، اب میں نے تمہارے مقابلے میں کیا کیا ہے؟ کیا افرائیم کے انگور نکالنا ابیزر کی شراب سے بہتر نہیں؟ \n3۔ خدا نے مدیان کے شہزادے، اوریب اور زیب کو تمہارے حوالے کر دیا ہے: اور میں تمہارے مقابلے میں کیا کر سکتا تھا؟ پھر ان کا غصہ اس پر کم ہو گیا، جب اس نے یہ کہا۔ {غصہ: عبرانی۔ روح}\n4۔ اور جدعون اردن آیا، {اور} گزر گیا، وہ اور وہ تین سو آدمی جو اس کے ساتھ تھے، بے ہوش مگر ان کا پیچھا کر رہے تھے۔ \n5۔ اور اس نے سکوت کے لوگوں سے کہا، میں تم سے دعا کرتا ہوں کہ میرے پیروکاروں کو روٹی کے ٹکڑے دو؛ کیونکہ وہ بے ہوش ہو گئے ہیں، اور میں مدیان کے بادشاہوں زباہ اور زلمنا کے پیچھے جا رہا ہوں۔ \n6۔ اور سکوتھ کے شہزادوں نے کہا، {کیا اب زباہ اور زلمنا کے ہاتھ تمہارے ہاتھ میں ہیں، کہ ہم تمہاری فوج کو روٹی دیں؟ \n7۔ اور جدعون نے فرمایا، لہٰذا جب خداوند زباہ اور زلمنا کو میرے ہاتھ میں دے گا، تو میں تمہارے گوشت کو صحرا کے کانٹوں اور کانٹوں سے پھاڑ دوں گا۔ {پھاڑو: عبرانی۔ تھریش}\n8۔ اور وہ وہاں سے پینویل گیا، اور اسی طرح ان سے بات کی: اور پینویل کے لوگوں نے اسے ویسے ہی جواب دیا جیسے سکوتھ کے لوگوں نے جواب دیا تھا۔ \n9۔ اور اس نے پینوئل کے لوگوں سے بھی کہا، جب میں امن کے ساتھ واپس آؤں گا تو اس مینار کو توڑ دوں گا۔ \n10۔ اب زباہ اور زلمنا کارکور میں تھے، اور ان کے لشکر تقریبا پندرہ ہزار {مرد}، جو مشرق کے بچوں کے تمام لشکروں میں سے باقی تھے: کیونکہ وہاں ایک لاکھ بیس ہزار آدمی مارے جنہوں نے تلوار نکالی۔ {وہ لوگ جو...: یا، ہر ایک تلوار نکال رہا تھا}\n11۔ اور جدعون ان لوگوں کے راستے گیا جو نوبہ اور یوگبیہ کے مشرق میں خیموں میں رہتے تھے، اور لشکر کو مار ڈالا، کیونکہ لشکر محفوظ تھا۔ \n12۔ اور جب زباہ اور زلمنا بھاگے، تو اس نے ان کا پیچھا کیا، اور مدیان کے دو بادشاہوں، زباہ اور زلمنا کو پکڑ لیا اور تمام لشکر کو پریشان کر دیا۔ {پریشان: عبرانی۔ خوفزدہ}\n13۔ اور جدعون، یوآش کا بیٹا، سورج نکلنے سے پہلے ہی جنگ سے واپس آیا، \n14۔ اور اس نے سکوتھ کے مردوں میں سے ایک نوجوان کو پکڑ کر اس سے پوچھا: اور اس نے اسے سکوتھ کے شہزادوں اور اس کے بزرگوں کی تفصیل دی، {حتیٰ کہ} تیس سترہ آدمی۔ {بیان شدہ: عبرانی تحریر}\n15۔ اور وہ سکوت کے لوگوں کے پاس آیا اور کہا، دیکھو زباہ اور زلمنا، جن کے ساتھ تم نے مجھے ڈانٹا تھا، کہہ رہا تھا، {کیا اب زباہ اور زلمنا کے ہاتھ تمہارے ہاتھ میں ہیں، تاکہ ہم تمہارے تھکے ہوئے لوگوں کو روٹی دیں؟' \n16۔ اور اس نے شہر کے بزرگ، جنگل کے کانٹے اور کانٹے لیے، اور ان کے ساتھ سکوتھ کے لوگوں کو تعلیم دی۔ {سکھایا گیا: عبرانی۔ جاننے کے لیے}\n17۔ اور اس نے پینوئل کے مینار کو گرا دیا اور شہر کے لوگوں کو قتل کر دیا۔ \n18۔ پھر اس نے زباہ اور زلمنا سے کہا، تم نے تابور میں کس قسم کے لوگ مارے؟ اور انہوں نے جواب دیا، جیسے تم ہو، ویسے ہی وہ بھی تھے؛ ہر ایک بادشاہ کے بچوں کی طرح تھا۔ {مشابہ...: عبرانی۔ شکل کے مطابق وغیرہ}\n19۔ اور اس نے کہا، وہ میرے بھائی تھے، یہاں تک کہ میری ماں کے بیٹے بھی: جیسا کہ خداوند زندہ ہے، اگر تم نے انہیں زندہ بچایا ہوتا تو میں تمہیں قتل نہ کرتا۔ \n20۔ اور اس نے اپنے پہلے بیٹے جیتر سے کہا، اوپر، {اور} انہیں مار ڈالو۔ لیکن نوجوان نے اپنی تلوار نہیں نکالی: کیونکہ وہ ڈرتا تھا، کیونکہ وہ ابھی جوان تھا۔ \n21. پھر زباہ اور زلمنا نے کہا، اٹھو اور ہم پر گر جاؤ، کیونکہ جیسے انسان ہے، ویسے ہی اس کی طاقت بھی ہے۔ اور جدعون اٹھا، زباہ اور زلمنا کو مار ڈالا، اور ان کے اونٹوں کی گردن پر لگے زیورات لے لیے۔ {زیورات: یا چاند کی طرح زیورات}\n22۔ پھر اسرائیل کے لوگوں نے گیدئون سے کہا، تو ہم پر حکمرانی کر، تم، اپنے بیٹے اور اپنے بیٹے کے بیٹے پر بھی، کیونکہ تم نے ہمیں مدیان کے ہاتھوں سے بچا لیا ہے۔ \n23۔ اور گیدعون نے ان سے کہا، میں تم پر حکومت نہیں کروں گا، نہ ہی میرا بیٹا تم پر حکومت کرے گا: خداوند تم پر حکمرانی کرے گا۔ \n24۔ اور گیدعون نے ان سے کہا، میں تم سے ایک درخواست چاہتا ہوں کہ تم مجھے ہر انسان کو اس کے شکار کے بالیاں دو۔ (کیونکہ ان کے پاس سونے کی بالیاں تھیں، کیونکہ وہ اسماعیلی تھے۔)\n25۔ اور انہوں نے جواب دیا، ہم خوش دلی سے {انہیں} دیں گے۔ اور انہوں نے ایک لباس پھیلایا، اور ہر آدمی کو اس کے شکار کے بالیاں اس میں ڈال دیں۔ \n26۔ اور اس نے جو سونے کی بالیاں مانگی تھیں، ان کا وزن ایک ہزار سات سو {شیکل} سونے کا تھا؛ زیورات، کالر، اور مدین کے بادشاہوں پر {تھا} کے ارغوانی لباس کے علاوہ، اور ان زنجیروں کے ساتھ جو ان کے اونٹوں کی گردن میں لپٹی ہوئی تھیں۔ {کالر: یا، میٹھے جواہرات}\n27۔ اور جدعون نے اس سے ایک ایفود بنایا، اور اسے اپنے شہر میں اوفرہ میں رکھا: اور سارا اسرائیل وہاں اس کے پیچھے ایک طوائف بن گیا، جو جدعون اور اس کے گھر کے لیے جال بن گیا۔ \n28۔ یوں مدیان کو بنی اسرائیل کے سامنے زیر کر دیا گیا، یہاں تک کہ انہوں نے اپنے سر نہیں اٹھائے۔ اور ملک چالیس سال تک جدعون کے زمانے میں خاموش رہا۔ \n29۔ اور یروبعل، جو یوآش کا بیٹا تھا، جا کر اپنے ہی گھر میں رہا۔ \n30۔ اور جدعون کے جسم کے تین سو اور دس بیٹے پیدا ہوئے: کیونکہ اس کی کئی بیویاں تھیں۔ {اس کی...: عبرانی۔ ران سے باہر نکلتی ہوئی}\n31۔ اور اس کی محبوبہ جو {تھی} شیکم میں، اس نے اسے ایک بیٹا بھی دیا، جس کا نام اس نے ابیملک رکھا۔ {پکارا: عبرانی۔ سیٹ}\n32۔ اور جدعون، یوآش کا بیٹا، بڑی عمر میں فوت ہو گیا، اور اسے اپنے والد یوآش کی قبر میں، ابیعزریوں کی اوفراہ میں دفن کیا گیا۔ \n33۔ اور جیسے ہی جدعون مر گیا، ایسا ہوا کہ بنی اسرائیل دوبارہ پلٹ گئے، اور بعلیم کے پیچھے بدکاری کرنے لگے، اور بعلبریت کو اپنا خدا بنا لیا۔ \n34۔ اور بنی اسرائیل نے اپنے خدا خداوند کو یاد نہیں کیا، جس نے انہیں ہر طرف سے ان کے دشمنوں کے ہاتھوں سے بچایا: \n35. نہ ہی انہوں نے یرباعل کے گھر، یعنی جدعون کے ساتھ مہربانی کی، جیسا کہ اس نے اسرائیل کے لیے کیا تھا۔","1۔ اور ابیملک، یرباعل کا بیٹا، اپنی ماں کے بھائیوں کے پاس شیکم گیا، اور ان سے اور اپنی ماں کے باپ کے گھر کے تمام خاندان سے بات چیت کی، اور کہا، \n2۔ میں تم سے دعا کرتا ہوں، شیکم کے تمام مردوں کے کانوں میں کہو، کیا تمہارے لیے بہتر ہے، یا یہ کہ یرباعل کے تمام بیٹے، جو کہ تیس اور دس افراد ہیں، تم پر حکومت کریں، یا وہ ایک تم پر حکمرانی کرے؟ یہ بھی یاد رکھو کہ میں تمہاری ہڈی اور تمہارا گوشت ہوں۔ {کیا...: عبرانی۔ کیا اچھا ہے؟ کیا ہے، وغیرہ}\n3۔ اور اس کی ماں کے بھائیوں نے اس کے بارے میں شیکم کے تمام مردوں کے کانوں میں یہ سب باتیں کیں: اور ان کے دل ابیملک کی پیروی کرنے لگے؛ کیونکہ انہوں نے کہا، وہ ہمارا بھائی ہے۔ {پیروی کرنے کے لیے: عبرانی۔ بعد میں}\n4۔ اور انہوں نے اسے بعلبیرتھ کے گھر سے تیس اور دس چاندی کے سکے دیے، جن سے ابیمیلک نے بے کار اور کم عمر لوگوں کو ملازمت دی، جو اس کے پیچھے آئے۔ \n5۔ اور وہ اپنے والد کے گھر اوفرہ گیا، اور اپنے بھائیوں کو یروبعل کے بیٹوں کو، جو کہ تیس اور دس افراد تھے، ایک پتھر پر مار ڈالا؛ پھر بھی یروباعل کا سب سے چھوٹا بیٹا یوتھام بچا تھا؛ کیونکہ وہ چھپ گیا۔ \n6۔ اور شیکم کے تمام لوگ اکٹھے ہوئے، اور میلو کے تمام خاندان نے اکٹھے ہو کر ابیمیلک کو بادشاہ بنایا، اس ستون کے میدان کے پاس جو {تھا} شیکم میں۔ {میدان: یا، بلوط}\n7۔ اور جب انہوں نے یہ بات یوتھم کو سنائی، تو وہ گیا اور کوہ گریزیم کی چوٹی پر کھڑا ہو گیا، اپنی آواز بلند کی، پکارا اور ان سے کہا، اے شیکم کے لوگو، میری بات سنو تاکہ خدا تمہاری بات سن سکے۔ \n8۔ درخت {ایک وقت} نکلے تاکہ ان پر بادشاہ کو مسح کریں؛ اور انہوں نے زیتون کے درخت سے کہا، تو ہم پر حکمرانی کر۔ \n9۔ لیکن زیتون کے درخت نے ان سے کہا، کیا میں اپنی موٹاپی چھوڑ دوں، جس سے وہ خدا اور انسان کی عزت کرتے ہیں، اور درختوں پر ترقی کے لیے جاؤں؟ {جاؤ...: یا، دوسرے درختوں کے لیے اوپر نیچے جاؤں}\n10۔ اور درختوں نے انجیر کے درخت سے کہا، آؤ، {اور} ہم پر حکومت کرو۔ \n11۔ لیکن انجیر کے درخت نے ان سے کہا، کیا میں اپنی مٹھاس اور اچھے پھل کو چھوڑ کر درختوں پر ترقی پانے جاؤں؟ \n12۔ پھر درختوں نے بیل سے کہا، آؤ، {اور} ہم پر حکومت کرو۔ \n13۔ اور بیل نے ان سے کہا، کیا میں اپنی شراب چھوڑ دوں، جو خدا اور انسان کو خوش کرتی ہے، اور درختوں پر ترقی کے لیے جاؤں؟ \n14. پھر تمام درختوں نے بریمبل سے کہا، آؤ، {اور} ہم پر حکومت کرو۔ {برامبل: یا، تھسل}\n15۔ اور کانٹے نے درختوں سے کہا، اگر تم واقعی مجھے اپنے اوپر بادشاہ مقرر کرو گے، تو آؤ اور میرے سائے پر بھروسہ کرو: اور اگر نہیں، تو جھاڑیوں سے آگ نکلے، اور لبنان کے دیودار کو کھا جائے۔ \n16۔ اب اگر تم نے سچے اور مخلص طریقے سے کیا ہے کہ تم نے ابیمیلک کو بادشاہ بنایا، اور اگر تم نے یربعل اور اس کے گھر کے ساتھ اچھا سلوک کیا ہے، اور اس کے ہاتھوں کے مستحق کے مطابق اس کے ساتھ کیا ہے؛ \n17۔ (کیونکہ میرے والد نے تمہارے لیے لڑائی کی، اپنی زندگی دور تک سفر کیا، اور تمہیں مدیان کے ہاتھوں سے آزاد کرایا: {مہم جوئی...: عبرانی۔ اپنی جان ڈال دو}\n18۔ اور تم آج میرے والد کے گھر کے خلاف اٹھ کھڑے ہوئے ہو، اور اس کے بیٹوں کو ایک پتھر پر مارے ہو، اور اپنی خادمہ کے بیٹے ابیملک، کو شیکم کے مردوں پر بادشاہ بنا دیا ہے، کیونکہ وہ تمہارا بھائی ہے؛)\n19۔ اگر تم نے آج یروبعل اور اس کے گھر کے ساتھ سچے اور مخلص سلوک کیے ہیں، تو ابیملک میں خوش رہو، اور وہ بھی تم میں خوش ہو: \n20۔ اگر ایسا نہ ہو تو ابیملک سے آگ نکلے، اور شیکم کے مردوں اور میلو کے گھرانے کو نگل جائے؛ اور شکم کے لوگوں اور میلو کے گھر سے آگ نکل کر ابیملک کو نگل جائے۔ \n21۔ اور یوتام بھاگ گیا، بھاگ گیا، بیر گیا اور اپنے بھائی ابیملیک کے خوف سے وہاں رہنے لگا۔ \n22۔ جب ابیملک نے اسرائیل پر تین سال حکومت کی، \n23۔ پھر خدا نے ابیملک اور شیکم کے لوگوں کے درمیان ایک شیطانی روح بھیجی؛ اور شیکم کے لوگوں نے ابیملک کے ساتھ دھوکہ دہی کی: \n24۔ تاکہ یربعل کے تیسٹھ اور دس بیٹوں کے ساتھ جو ظلم ہوا، وہ آ جائے، اور ان کا خون ابیملک، ان کے بھائی پر بہہ جائے، جس نے انہیں قتل کیا؛ اور شیکم کے مردوں پر، جنہوں نے اس کے بھائیوں کے قتل میں اس کی مدد کی۔ {مدد...: حب۔ اپنے ہاتھوں کو قتل کرنے کے لیے مضبوط کیا}\n25۔ اور شیخیم کے لوگوں نے اس کے لیے پہاڑوں کی چوٹی پر جھوٹے لگا دیے، اور جو کچھ بھی ان کے پاس آیا اسے لوٹا: اور ابیمیلک کو بتایا گیا۔ \n26۔ اور گال، ابن ایبید، اپنے بھائیوں کے ساتھ آیا، اور شیکم کے پاس گیا: اور شیکم کے لوگوں نے اس پر اعتماد کیا۔ \n27۔ اور وہ کھیتوں میں نکلے، اپنے انگور کے باغات جمع کیے، انگور کے باغات پر چلے، خوش ہوئے، اور اپنے خدا کے گھر میں گئے، کھایا، پیا، اور ابیملک کو لعنت دی۔ {خوشی: یا، گیت}\n28۔ اور عبید کے بیٹے گال نے کہا، ابیملک کون ہے، اور شیکم کون ہے، کہ ہم اس کی خدمت کریں؟ کیا وہ یربعل کا بیٹا نہیں ہے؟ اور زبول اس کا افسر؟ حمور کے آدمیوں کی خدمت کرو، جو شیکم کا باپ ہے: کیونکہ ہم اس کی خدمت کیوں کریں؟ \n29۔ اور کاش یہ لوگ میرے ہاتھ میں ہوتے! تب میں ابیملک کو ہٹانا چاہتا۔ اور اس نے ابیملک سے کہا، اپنی فوج بڑھاؤ اور باہر آؤ۔ \n30۔ اور جب شہر کے حکمران زبول نے گال بیٹے ایبید کے الفاظ سنے، تو اس کا غصہ بھڑک اٹھا۔ {جلایا گیا: یا، گرم}\n31۔ اور اس نے ابیملک کو خفیہ طور پر قاصد بھیجے اور کہا، دیکھو، گال ابن ایبید اور اس کے بھائی شیکم آ رہے ہیں؛ اور دیکھو، وہ شہر کو تمہارے خلاف مضبوط کرتے ہیں۔ {خفیہ طور پر: عبرانی۔ چالاکی سے یا، تورما کی طرف}\n32۔ اب رات کو جاگ جاؤ، تم اور وہ لوگ جو تمہارے ساتھ ہیں، کھیت میں انتظار کرو: \n33۔ اور یہ ہوگا، {کہ} صبح کو، جیسے ہی سورج نکلے گا، تم جلدی اٹھو گے، اور شہر میں داخل ہو جاؤ گے: اور دیکھو، {جب} وہ اور اس کے ساتھ لوگ تمہارے خلاف نکلیں گے، تب تم ان کے ساتھ وہی کرو جیسا تمہیں موقع ملے۔ {جیسا کہ تم چاہو گے...: عبرانی۔ جیسا تمہارا ہاتھ ملے گا}\n34۔ اور ابیملک اٹھ کھڑا ہوا، اور وہ سب لوگ جو اس کے ساتھ تھے، رات کو، اور چار گروہوں میں شیکم کے خلاف انتظار کرنے لگے۔ \n35۔ اور گال ابن ایبید باہر نکلا، اور شہر کے دروازے کے دروازے میں کھڑا ہو گیا: اور ابیمیلک اٹھ کھڑا ہوا، اور اس کے ساتھ موجود لوگ انتظار سے اٹھ کھڑے ہوئے۔ \n36۔ اور جب گال نے لوگوں کو دیکھا تو اس نے زبول سے کہا، دیکھو، پہاڑوں کی چوٹی سے لوگ نیچے آ رہے ہیں۔ اور زبول نے اسے کہا، تو پہاڑوں کے سائے کو ایسے دیکھتے ہو جیسے وہ انسان ہوں۔ \n37۔ اور گال نے دوبارہ کہا اور کہا، دیکھو لوگ زمین کے بیچ سے نیچے آتے ہیں، اور ایک اور گروہ میوننیم کے میدان سے آتا ہے۔ {درمیان: عبرانی ناف} {میوننیم: یا، زمانوں کے خیال رکھنے والے}\n38۔ پھر زبل نے اس سے کہا، اب تمہارا منہ کہاں ہے، جس سے تم نے کہا، ابیملک کون ہے، کہ ہم اس کی خدمت کریں؟ کیا یہ وہ لوگ نہیں جنہیں تم نے حقیر سمجھا؟ باہر جاؤ، میں دعا کرتا ہوں، اور ان سے لڑو۔ \n39۔ اور گال شیکم کے لوگوں کے سامنے نکلا اور ابیملک سے لڑا۔ \n40۔ اور ابیملک نے اس کا پیچھا کیا، اور وہ اس کے سامنے بھاگ گیا، اور بہت سے لوگ گر کر زخمی ہو گئے، {حتیٰ کہ} دروازے کے داخلے تک۔ \n41۔ اور ابیملک آرومہ میں رہا: اور زبول نے گال اور اس کے بھائیوں کو نکال دیا تاکہ وہ شیکم میں نہ رہیں۔ \n42۔ اور کل ایسا ہوا کہ لوگ کھیت میں نکل گئے؛ اور انہوں نے ابیملک کو بتایا۔ \n43۔ اور اس نے لوگوں کو لے کر تین گروہوں میں تقسیم کیا، میدان میں انتظار کیا، اور دیکھا، اور دیکھتے ہوئے لوگ شہر سے باہر آ گئے؛ اور اس نے ان کے خلاف اٹھ کھڑا ہو کر انہیں شکست دی۔ \n44۔ اور ابیملک، اور اس کے ساتھ موجود گروہ آگے بڑھے اور شہر کے دروازے کے دروازے پر کھڑے ہو گئے، اور دو {دیگر} گروہ کھیتوں میں موجود تمام {لوگ} پر دوڑے اور انہیں قتل کر دیا۔ \n45۔ اور ابیملک نے سارا دن شہر کے خلاف لڑائی کی؛ اور اس نے شہر پر قبضہ کیا، اور وہاں موجود لوگوں کو مار ڈالا، شہر کو شکست دی اور اسے نمک سے بویا۔ \n46۔ اور جب شیکم کے مینار کے تمام لوگوں نے یہ سنا، تو وہ خدا بیرتھ کے گھر میں داخل ہو گئے۔ \n47۔ اور ابیملک کو بتایا گیا کہ شیکم کے مینار کے تمام مرد اکٹھے ہو گئے ہیں۔ \n48۔ اور ابیمیلک نے اسے زالمون پر سوار کیا، وہ اور وہ سب لوگ جو اس کے ساتھ تھے؛ اور ابیمیلک نے اپنے ہاتھ میں کلہاڑی لی، درختوں سے ایک شاخ کاٹ کر اسے اپنے کندھے پر رکھا، اور ان لوگوں سے کہا جو اس کے ساتھ تھے، جو تم نے مجھے کرتے دیکھا ہے، جلدی کرو، {اور} وہی کرو جو میں نے {کیا}۔ {میں کرتا ہوں: عبرانی۔ میں نے کیا ہے}\n49۔ اور اسی طرح تمام لوگوں نے ہر آدمی کی شاخ کاٹ دی، ابیمیلک کے پیچھے گئے، اور انہیں ہولڈ میں ڈال دیا، اور ان پر قلعہ آگ لگا دی؛ یوں شیکم کے مینار کے تمام مرد بھی مارے گئے، تقریبا ایک ہزار مرد اور عورتیں۔ \n50۔ پھر ابیملک تھیبز گیا، تھیبز کے خلاف خیمہ لگایا، اور اسے فتح کر لیا۔ \n51۔ لیکن شہر کے اندر ایک مضبوط برج تھا، اور وہاں سے تمام مرد و عورتیں، اور شہر کے سب لوگ، انہیں بند کر کے مینار کی چوٹی تک لے گئے۔ \n52۔ اور ابیملکھ مینار کے پاس آیا، اس کے خلاف لڑا، اور زور سے مینار کے دروازے تک جا کر اسے آگ سے جلا دیا۔ \n53۔ اور ایک عورت نے ابیملک کے سر پر چکی کا ایک ٹکڑا پھینکا، اور یہ سب اس کے کھوپڑی کو توڑنے کے لیے۔ \n54۔ پھر اس نے جلدی سے نوجوان کو اپنے زرہ بردار کو بلایا، اور کہا، اپنی تلوار نکالو اور مجھے مار دو، جو لوگ میرے بارے میں نہیں کہتے، ایک عورت نے اسے مار ڈالا۔ اور اس کے نوجوان نے اسے گھونپ دیا، اور وہ مر گیا۔ \n55۔ اور جب اسرائیل کے لوگوں نے دیکھا کہ ابیمیلک مر چکا ہے، تو وہ ہر آدمی کو اس کی جگہ چھوڑ گئے۔ \n56۔ یوں خدا نے ابیملک کی برائی کی، جو اس نے اپنے والد کے ساتھ کی، جب اس نے اپنے ستر بھائیوں کو قتل کیا: \n57۔ اور خدا نے شیکم کے لوگوں کی تمام برائی ان کے سروں پر ڈال دی: اور ان پر یروباعل کے بیٹے یوتام کی لعنت آ گئی۔","1۔ اور ابیمیلک کے بعد اسرائیل ٹولا کا دفاع کرنے آیا، جو پواہ کا بیٹا تھا، دودو کا بیٹا، یساکر کا آدمی تھا؛ اور وہ افریم پہاڑ کے شامیر میں رہا۔ {دفاع: یا، نجات دلو: عبرانی۔ بچا}\n2۔ اور اس نے اسرائیل کو بیس سال اور تئیس سال کا فیصلہ کیا، وفات پا گئی، اور شامیر میں دفن ہوئی۔ \n3۔ اور اس کے بعد یائر، جو گلعاد تھا، پیدا ہوا اور اس نے بیس سال بائیس سال اسرائیل کا فیصلہ کیا۔ \n4۔ اور اس کے تیس بیٹے تھے جو تیس گدھے کے کولٹس پر سوار تھے، اور ان کے پاس تیس شہر تھے، جنہیں آج تک ہاووتجائر کہا جاتا ہے، جو گلعاد کی زمین میں ہیں۔ {ہووتجیئر: یا، یائر کے گاؤں}\n5۔ اور یائر فوت ہو گیا، اور کیمون میں دفن ہوا۔ \n6۔ اور بنی اسرائیل نے خداوند کے سامنے پھر سے برا کیا، بعلیم، اشتاروت، شام کے دیوتاؤں، زیدون کے دیوتاؤں، موآب کے دیوتاؤں، عمون کے بچوں کے دیوتاؤں اور فلسطینیوں کے دیوتاؤں کی عبادت کی، اور خداوند کو چھوڑ دیا، اور اس کی عبادت نہیں کی۔ \n7۔ اور خداوند کا غصہ اسرائیل کے خلاف شدید تھا، اور اس نے انہیں فلسطینیوں اور آمون کے بچوں کے ہاتھوں میں بیچ دیا۔ \n8۔ اور اس سال انہوں نے بنی اسرائیل کو تنگ اور مظلوم بنایا: اٹھارہ سال، وہ تمام بنی اسرائیل جو اردن کے دوسری طرف اموری کی سرزمین میں تھے، جو گلعاد میں ہے۔ {مظلوم: عبرانی۔ کچلے گئے}\n9۔ مزید برآں، آمون کے بچے اردن کے پار سے گزر کر یہوداہ، بنیمن، اور افریم کے گھرانے کے خلاف لڑنے لگے؛ جس سے اسرائیل بہت پریشان ہوا۔ \n10۔ اور بنی اسرائیل نے خداوند سے پکارا، کہا: ہم نے تیرے خلاف گناہ کیا ہے، کیونکہ ہم نے اپنے خدا کو چھوڑ دیا اور بعلیم کی خدمت بھی کی۔ \n11۔ اور خداوند نے بنی اسرائیل سے کہا، {کیا} نے {میں تمہیں مصریوں سے، اموریوں، آمون کے بچوں اور فلسطینیوں سے نجات نہیں دی؟' \n12۔ زیدونیوں نے، امالیقی اور ماونیوں نے بھی تم پر ظلم کیا؛ اور تم نے مجھ سے پکارا، اور میں نے تمہیں ان کے ہاتھوں سے آزاد کیا۔ \n13۔ پھر بھی تم نے مجھے چھوڑ دیا اور دوسرے دیوتاؤں کی خدمت کی، اسی لیے میں تمہیں مزید نجات نہیں دوں گا۔ \n14۔ جاؤ اور ان دیوتاؤں سے پکار جاؤ جنہیں تم نے چنا ہے؛ وہ تمہیں تمہاری مصیبت کے وقت نجات دیں۔ \n15۔ اور بنی اسرائیل نے خداوند سے کہا، ہم نے گناہ کیا ہے: تو ہمارے ساتھ وہ کر جو تمہیں اچھا لگے؛ آج ہم دعا کرتے ہیں کہ صرف ہمیں نجات دے۔ {ظاہر ہوتا ہے...: عبرانی۔ تیری نظر میں اچھا ہے}\n16۔ اور انہوں نے اپنے اندر سے عجیب دیوتاؤں کو دور کر دیا، اور خداوند کی خدمت کی: اور اس کی روح اسرائیل کی مصیبت پر غمگین ہوئی۔ {عجیب...: عبرانی۔ اجنبیوں کے دیوتا} {غمگین: عبرانی۔ مختصر}\n17۔ پھر آمون کے بچے اکٹھے ہوئے اور گلعاد میں خیمہ زن ہو گئے۔ اور بنی اسرائیل اکٹھے ہو گئے، اور مزپے میں خیمہ زن ہو گئے۔ {جمع ہوئے: عبرانی۔ چیخے}\n18۔ اور گیلعاد کے لوگ {اور} شہزادوں نے ایک دوسرے سے کہا، وہ کون سا آدمی ہے جو آمون کے بچوں کے خلاف لڑنا شروع کرے گا؟ وہ گلعاد کے تمام باشندوں کا سربراہ ہوگا۔","1۔ اب یفتاہ گلعاد ایک بہادر آدمی تھا، اور وہ ایک کا بیٹا تھا: اور گیلعاد نے یفتاہ کو جنم دیا۔ {یفتاح: گری. یفتھا} {ایک طوائف: عبرانی۔ ایک عورت، ایک طوائف}\n2۔ اور گلعاد کی بیوی نے اسے بیٹے پیدا کیے؛ اور اس کی بیوی کے بیٹے بڑے ہوئے، اور انہوں نے یفتاح کو نکال دیا، اور اس سے کہا، تم ہمارے باپ کے گھر میں وارث نہیں بنو گے؛ کیونکہ تم ایک اجنبی عورت کے بیٹے ہو۔\n3۔ پھر یفتاح اپنے بھائیوں سے بھاگ کر طوب کی سرزمین میں بسنے لگا: اور وہاں بے کار لوگ جمع ہوئے اور اس کے ساتھ باہر نکل گئے۔ {از: عبرانی سے۔ چہرے سے}\n4۔ اور وقت کے ساتھ ایسا ہوا کہ آمون کے اولاد نے اسرائیل کے خلاف جنگ کی۔ {عمل میں...: عبرانی دنوں کے بعد}\n5۔ اور یوں ہوا جب آمون کے اولاد نے اسرائیل کے خلاف جنگ کی، تو گلعاد کے بزرگ یفتاح کو طوب کی سرزمین سے لینے گئے:\n6۔ اور انہوں نے یفتاح سے کہا، آؤ اور ہمارا کپتان بنو، تاکہ ہم آمون کے بچوں کے ساتھ لڑ سکیں۔\n7۔ اور یفتاح نے گلعاد کے بزرگوں سے کہا، کیا تم نے مجھ سے نفرت نہیں کی، اور مجھے میرے باپ کے گھر سے نکال دیا؟ اور تم اب میرے پاس کیوں آ رہے ہو جب تم پریشان ہو؟\n8۔ اور گیلعاد کے بزرگوں نے یفتاہ سے کہا، لہٰذا ہم اب آپ کی طرف رجوع کرتے ہیں تاکہ آپ ہمارے ساتھ جائیں، اور آمون کے بچوں کے خلاف لڑیں، اور گیلعاد کے تمام باشندوں پر ہمارا سربراہ بنو۔\n9۔ اور یفتاح نے گلعاد کے بزرگوں سے کہا، اگر تم مجھے دوبارہ گھر لاؤ تاکہ میں آمون کے بچوں سے لڑوں، اور خداوند انہیں میرے سامنے بچائے، تو کیا میں تمہارا سر بنوں گا؟\n10۔ اور گلعاد کے بزرگوں نے یفت ہا سے کہا، اگر ہم تیرے الفاظ کے مطابق ایسا نہ کریں تو خداوند ہمارے درمیان گواہ بنو۔ {گواہ...: عبرانی۔ ہمارے درمیان سننے والا}\n11۔ پھر یفتاح گلعاد کے بزرگوں کے ساتھ گیا، اور لوگوں نے اسے ان کا سربراہ اور کپتان بنایا: اور یفتاح نے اپنے تمام الفاظ مزپے میں خداوند کے سامنے کہے۔\n12۔ اور یفتاح نے عمون کے بچوں کے بادشاہ کے پاس پیغامبر بھیجے اور کہا، \"تمہیں میرے ساتھ کیا کرنا ہے کہ تم میرے خلاف میرے ملک میں لڑنے آئے ہو؟\n13۔ اور آمون کے بچوں کے بادشاہ نے یفت ہا کے پیغامبروں کو جواب دیا، کیونکہ اسرائیل نے میری زمین چھین لی، جب وہ مصر سے نکلے، آرنون سے حتیٰ کہ یعقوب تک، اور پھر اردن تک: اب وہ زمینیں دوبارہ امن سے بحال کرو۔\n14۔ اور یفتاح نے دوبارہ عمون کے بچوں کے بادشاہ کے پاس پیغام بھیجے:\n15۔ اور اس سے کہا، یوں یفتاح کہتا ہے، اسرائیل نے موآب کی زمین اور آمون کے بچوں کی زمین نہیں چھینی۔\n16۔ لیکن جب اسرائیل مصر سے آیا، اور ویرانے سے گزرتا ہوا بحیرہ احمر تک پہنچا، اور قادیش پہنچا؛\n17۔ پھر اسرائیل نے ادوم کے بادشاہ کے پاس پیغامبر بھیجے اور کہا، مجھے، میں تم سے درخواست کرتا ہوں، تیری سرزمین سے گزرنے دو، لیکن ادوم کا بادشاہ اس کی بات نہیں سنتا۔ اسی طرح انہوں نے موآب کے بادشاہ کو بھیجا: لیکن وہ راضی نہ ہوا: اور اسرائیل قادیش میں ٹھہر گئے۔\n18۔ پھر وہ بیابان سے گزرے، اور ادم کی زمین اور موآب کی زمین کو گھیر لیا، اور موآب کی زمین کے مشرقی کنارے سے آئے، اور آرنون کے دوسری طرف زمین پر چڑھ گئے، لیکن موآب کی سرحد کے اندر نہیں آئے: کیونکہ آرنون موآب کی سرحد تھا۔\n19۔ اور اسرائیل نے اموریوں کے بادشاہ سیہون، ہیشبون کے بادشاہ کے پاس پیغامبر بھیجے؛ اور اسرائیل نے اس سے کہا، ہم دعا کرتے ہیں کہ ہم تیری زمین سے میرے مقام پر آ جائیں۔\n20۔ لیکن سیہون نے اسرائیل پر بھروسہ نہیں کیا کہ وہ اس کے ساحل سے گزرے گا: بلکہ سیہون نے اپنی تمام قوم کو اکٹھا کیا، جہاز میں شامل ہو کر اسرائیل کے خلاف لڑائی کی۔\n21۔ اور اسرائیل کے خداوند خدا نے سیحون اور اس کے تمام لوگوں کو اسرائیل کے ہاتھ میں دے دیا، اور انہوں نے انہیں شکست دی: یوں اسرائیل نے اس ملک کے باشندوں کے تمام اموریوں کی زمین پر قبضہ کر لیا۔\n22۔ اور انہوں نے اموریوں کے تمام ساحلوں پر قبضہ کر لیا، آرنون سے لے کر یعقوب تک، اور ویرانے سے لے کر اردن تک۔\n23. تو اب اسرائیل کے خداوند خدا نے اپنے قوم اسرائیل کے سامنے اموریوں کو بے دخل کر دیا ہے، اور کیا تمہیں اس پر قبضہ کرنا چاہیے؟\n24. کیا تم وہ نہیں رکھو گے جو تمہارا خدا تمہیں کیموش دیتا ہے؟ تو جسے بھی ہمارا خداوند ہمارے سامنے سے نکال دے گا، وہ ہم اپنے پاس ہوں گے۔\n25۔ اور اب کیا تم موآب کے بادشاہ زپور کے بیٹے بالاک سے بہتر کوئی چیز ہو؟ کیا اس نے کبھی اسرائیل کے خلاف لڑائی کی، یا کبھی ان کے خلاف لڑا،\n26. جب اسرائیل ہیشبون اور اس کے قصبوں میں، اور آروئر اور اس کے قصبوں میں، اور آرنون کے ساحلوں کے کنارے تمام شہروں میں تین سو سال رہے؟ تو پھر تم نے اس وقت میں انہیں کیوں نہیں بحال کیا؟\n27۔ اسی لیے میں نے تمہارے خلاف گناہ نہیں کیا، بلکہ تو میرے خلاف جنگ کر کے مجھ پر ظلم کرتے ہو: خداوند جج آج بنی اسرائیل اور آمون کے بچوں کے درمیان فیصلہ کرے۔\n28۔ تاہم آمون کے بچوں کے بادشاہ نے یفتاہ کے الفاظ کو نہیں سنا جو اس نے اسے بھیجے تھے۔\n29۔ پھر خداوند کا روح یفتاح پر آیا، اور وہ گلعاد اور منسی کے پار سے گزرا، اور گلعاد کے مزپیہ سے گزرا، اور گیلیاد کے مزپیہ سے آمون کے بچوں کے پاس آیا۔\n30۔ اور یفتاح نے خداوند سے عہد کیا، اور کہا، اگر تم ہمیشہ آمون کے بچوں کو میرے ہاتھوں میں دے دو،\n31۔ پھر یہ ہوگا کہ جو کچھ بھی میرے گھر کے دروازے سے نکلے گا، جب میں آمون کے بچوں سے امن کے ساتھ واپس آؤں گا، وہ یقینا خداوند کا ہوگا، اور میں اسے جلانے کی قربانی کے طور پر پیش کروں گا۔ {جو بھی ہو...: عبرانی۔ جو نکلے گا، جو آئے گا} {اور...: یا، یا میں اسے پیش کروں گا، وغیرہ}\n32۔ یوں یفتاح عمون کے بچوں کے پاس گیا تاکہ ان کے خلاف لڑے؛ اور خداوند نے انہیں اپنے ہاتھوں میں دیا۔\n33۔ اور اس نے انہیں آروئر سے مار ڈالا، یہاں تک کہ تم منیٹھ پہنچے، {حتیٰ کہ} بیس شہروں کو، اور انگور کے میدان تک، بہت بڑا قتل عام سے۔ یوں آمون کے بچے بنی اسرائیل کے سامنے مغلوب ہو گئے۔ {میدان: یا، ہابل}\n34۔ اور یفتاح مزپیہ کے گھر آیا، اور دیکھتے ہی اس کی بیٹی اس کے استقبال کے لیے ٹیمبرل اور رقص کے ساتھ آئی: اور وہ اس کی اکلوتی اولاد تھی؛ اس کے علاوہ اس کا نہ بیٹا تھا اور نہ بیٹی۔ {اس کے علاوہ...: یا، اس کا اپنا بیٹا یا بیٹی نہیں تھا: عبرانی۔ اپنے بارے میں}\n35۔ اور جب اس نے اسے دیکھا تو اس نے اپنے کپڑے پھاڑ دیے اور کہا، افسوس، میری بیٹی! تم نے مجھے بہت نیچا دکھایا، اور تم ان میں سے ہو جو مجھے پریشان کرتے ہیں: کیونکہ میں نے خداوند کے لیے اپنا منہ کھول دیا ہے، اور میں واپس نہیں جا سکتا۔\n36۔ اور اس نے اس سے کہا، میرے باپ، اگر تم نے خداوند کے لیے اپنا منہ کھولا ہے، تو میرے ساتھ وہی کرو جو تمہارے منہ سے نکلا؛ کیونکہ خداوند نے تمہارے دشمنوں سے انتقام لیا ہے، {حتیٰ کہ} عمون کے بچوں سے بھی۔\n37۔ اور اس نے اپنے والد سے کہا، یہ کام میرے لیے ہو جائے: مجھے دو مہینے چھوڑ دو، تاکہ میں پہاڑوں پر اوپر نیچے جا سکوں اور اپنی پاکدامنی کا افسوس کر سکوں، میں اور میرے ساتھی۔ {اوپر جاؤ...: عبرانی۔ جاؤ اور نیچے جاؤ}\n38۔ اور اس نے کہا، جاؤ۔ اور اس نے اسے دو مہینے کے لیے بھیج دیا: اور وہ اپنے ساتھیوں کے ساتھ چلی گئی، اور پہاڑوں پر اپنی کنواری ہونے پر افسوس کرنے لگی۔\n39۔ اور دو ماہ کے آخر میں وہ اپنے والد کے پاس واپس آئی، جس نے اس کے ساتھ اپنے وعدے کے مطابق کیا جو اس نے کیا تھا: اور وہ کسی مرد کو نہیں جانتی تھی۔ اور یہ اسرائیل میں ایک رسم تھی، {رسم: یا، آرڈیننس}\n40۔ {یعنی} اسرائیل کی بیٹیاں سال میں چار دن یفتاح گلعاد کی بیٹی کے لیے ماتم کرنے جاتی تھیں۔ {سالانہ: عبرانی۔ سال بہ سال} {ماتم کرنے کے لیے: یا، بات کرنے کے لیے}","1۔ اور افرائیم کے لوگ اکٹھے ہوئے، شمال کی طرف گئے، اور یفتاح سے کہا، کیوں تم آ کر آمون کے بچوں کے خلاف لڑنے آئے ہو، اور ہمیں اپنے ساتھ جانے کے لیے کیوں نہیں بلایا؟ ہم تمہارے گھر کو آگ سے جلا دیں گے۔ {جمع کیا گیا...: عبرانی۔ پکارا گیا}\n2۔ اور یفتاح نے ان سے کہا، میں اور میرے لوگ آمون کے بچوں کے ساتھ شدید جھگڑے میں ہیں؛ اور جب میں نے تمہیں بلایا، تم نے مجھے ان کے ہاتھوں سے آزاد نہیں کیا۔\n3۔ اور جب میں نے دیکھا کہ تم نے مجھے نجات نہیں دی، تو میں نے اپنی جان اپنے ہاتھوں میں دے دی، اور آمون کے بچوں کے خلاف آگے بڑھ گیا، اور خداوند نے انہیں میرے ہاتھ میں دے دیا: تو پھر آج تم میرے پاس کیوں آئے ہو، میرے خلاف لڑنے کے لیے؟\n4۔ پھر یفتاح نے گلعاد کے تمام آدمیوں کو جمع کیا اور افرایم کے ساتھ لڑائی کی، اور گلعاد کے لوگوں نے افرائیم کو مارا، کیونکہ انہوں نے کہا، یوہ گلعاد کے لوگ افرایم کے فراری ہیں، اور مناسیوں میں بھی۔\n5۔ اور گلعادیوں نے افرائیمیوں کے سامنے اردن کے راستے لے لیے: اور ایسا ہی ہوا کہ جب وہ افریمی جو بچ نکلے تھے نے کہا، مجھے جانے دو؛ کہ گلعاد کے لوگوں نے اس سے کہا، کیا تم افریمی ہو؟ اگر اس نے کہا، نہیں؛\n6۔ پھر انہوں نے اس سے کہا، اب کہو شبولیت: اور اس نے کہا سیبولیت: کیونکہ وہ صحیح کہہ نہیں سکا۔ پھر انہوں نے اسے پکڑ لیا اور اردن کے راستوں پر قتل کر دیا: اور اس وقت افریمیوں میں چالیس دو ہزار مارے گئے۔\n7۔ اور یفتاح نے چھ سال اسرائیل کا فیصلہ کیا۔ پھر یفتاح گلعادی فوت ہوا، اور اسے گلعاد کے شہروں میں سے ایک میں دفن کیا گیا۔\n8۔ اور اس کے بعد بیت لحم کے ابزان نے اسرائیل کا فیصلہ کیا۔\n9۔ اور اس کے تیس بیٹے اور تیس بیٹیاں تھیں، جنہیں اس نے بیرون ملک بھیجا، اور اپنے بیٹوں کے لیے تیس بیٹیاں بیرون ملک سے لے آئے۔ اور اس نے اسرائیل کو سات سال کا فیصلہ کیا۔\n10۔ پھر ابزان وفات پا گئے اور بیت لحم میں دفن ہوئے۔\n11۔ اور اس کے بعد ایلون، جو زبولونی تھا، نے اسرائیل کا فیصلہ کیا؛ اور اس نے اسرائیل کو دس سال کی سزا دی۔\n12۔ اور ایلون زبولونائٹ فوت ہو گیا، اور اسے زبولون کے علاقے ایجالون میں دفن کیا گیا۔\n13۔ اور اس کے بعد عبدون، ہلیل کا بیٹا، جو پیراتھونی تھا، نے اسرائیل کا فیصلہ کیا۔\n14۔ اور اس کے چالیس بیٹے اور تیس بھتیجے تھے، جو تین سو اور دس گدھے کے گھوڑوں پر سوار تھے: اور اس نے اسرائیل کو آٹھ سال سزا دی۔ {بھتیجے: عبرانی۔ بیٹوں کے بیٹے}\n15۔ اور عبدون، ہلیل پیراثونی کا بیٹا، وفات پا گیا، اور اسے افرائیم کی سرزمین پر، امالیقیوں کے پہاڑ میں پیراتھون میں دفن کیا گیا۔","1۔ اور بنی اسرائیل نے خداوند کے سامنے پھر سے برا کیا؛ اور خداوند نے انہیں چالیس سال تک فلسطینیوں کے ہاتھ میں دے دیا۔ {کیا برائی...: عبرانی۔ کمٹ میں شامل کیا جاتا ہے، وغیرہ}\n2۔ اور زورہ کا ایک آدمی تھا، جو ڈینیوں کے خاندان سے تھا، جس کا نام منوح تھا؛ اور اس کی بیوی بانجھ تھی، اور ننگے نہیں تھی۔\n3۔ اور خداوند کے فرشتے نے عورت کو ظاہر کیا اور کہا، دیکھو، تم بانجھ ہو اور بچے کو جنم نہیں دیتی، لیکن تم حاملہ ہو گی اور بیٹا پیدا کرو گی۔\n4. اب میں تم سے درخواست کرتا ہوں کہ ہوشیار رہو، نہ شراب پیو نہ تیز شراب، اور کوئی ناپاک چیز نہ کھاؤ:\n5۔ کیونکہ دیکھو، تم حاملہ ہو گی اور بیٹا پیدا کرو گی؛ اور اس کے سر پر کوئی ریزر نہیں آئے گا: کیونکہ بچہ رحم سے ہی خدا کے لیے ناصری ہوگا، اور وہ اسرائیل کو فلسطینیوں کے ہاتھوں سے آزاد کرانا شروع کرے گا۔\n6۔ پھر عورت آئی اور اپنے شوہر کو بتایا، کہا، خدا کا ایک آدمی میرے پاس آیا، اور اس کا چہرہ خدا کے فرشتے جیسا تھا، بہت خوفناک: لیکن میں نے اس سے نہیں پوچھا کہ وہ کہاں سے ہے، نہ ہی اس نے اپنا نام بتایا:\n7۔ لیکن اس نے مجھ سے کہا، دیکھو، تم حاملہ ہو گی اور بیٹا پیدا کرو گی؛ اور اب نہ شراب پیو، نہ تیز مشروب، نہ کوئی ناپاک چیز کھاؤ، کیونکہ بچہ رحم سے لے کر موت تک خدا کے نزدیک ناصری رہے گا۔\n8۔ پھر منوہ نے خداوند سے درخواست کی اور کہا، اے میرے رب، وہ خدا کا آدمی جسے تو نے بھیجا ہے، ہمارے پاس واپس آئے، اور ہمیں سکھائے کہ ہم اس بچے کے ساتھ کیا کریں گے جو پیدا ہوگا۔\n9۔ اور خدا نے منوہ کی آواز سنی؛ اور خدا کا فرشتہ دوبارہ اس عورت کے پاس آیا جب وہ میدان میں بیٹھی تھی: لیکن منوہ اس کا شوہر اس کے ساتھ نہیں تھا۔\n10۔ اور عورت جلدی کر گئی، بھاگی، اور اپنے شوہر کو دکھایا، اور اسے کہا، دیکھو، وہ آدمی میرے سامنے آ گیا ہے، جو پچھلے دن میرے پاس آیا تھا۔\n11۔ اور منوہ اٹھا، اپنی بیوی کے پیچھے گیا، مرد کے پاس آیا اور اس سے کہا، کیا تم وہی آدمی ہو جس نے عورت سے بات کی؟ اور اس نے کہا، میں {ہوں}۔\n12۔ اور منوہ نے کہا، اب تمہارے الفاظ حقیقت بن جائیں۔ ہم بچے کو کیسے حکم دیں، اور اس کے ساتھ کیا کریں؟ {ہم کیسے آرڈر کریں...: عبرانی کیا طریقہ ہوگا، وغیرہ} {ہم کیسے کریں...: یا، وہ کیا کرے؟: عبرانی۔ اس کا کام کیا ہوگا؟}\n13۔ اور خداوند کے فرشتے نے منوہ سے کہا، جو کچھ میں نے عورت سے کہا اس میں سے خبردار رہے۔\n14. وہ انگور سے آنے والی کسی بھی چیز سے نہیں کھا سکتی، نہ شراب پی سکتی ہے نہ تیز پی، نہ ہی کوئی ناپاک چیز کھائے گی: جو کچھ میں نے اسے حکم دیا ہے وہ سب دیکھ لے۔\n15۔ اور منوہ نے خداوند کے فرشتے سے کہا، میں تم سے درخواست کرتا ہوں، آؤ تمہیں روک لیں، جب تک کہ ہم تمہارے لیے بچہ تیار نہ کر لیں۔ {تمہارے لیے: عبرانی۔ تمہارے سامنے\n16۔ اور خداوند کے فرشتے نے منوہ سے کہا، اگر تم مجھے روک بھی لو، تو میں تمہاری روٹی نہیں کھاؤں گا: اور اگر تم جلنے والی قربانی پیش کرو گے تو اسے خداوند کے سامنے پیش کرنا ہوگا۔ کیونکہ منوہ نہیں جانتا تھا کہ وہ خداوند کا فرشتہ ہے۔\n17۔ اور منوہ نے خداوند کے فرشتے سے کہا، \"تیرا نام کیا ہے، تاکہ جب تیری باتیں ہوں تو ہم تمہاری عزت کریں؟\n18۔ اور خداوند کے فرشتے نے اس سے کہا، تم میرے نام کے بارے میں اس طرح کیوں پوچھتے ہو، جب کہ یہ راز ہے؟ {راز: یا، شاندار}\n19۔ تو منواح نے ایک بچے کو گوشت کی قربانی کے ساتھ لیا اور اسے ایک چٹان پر خداوند کے سامنے پیش کیا: اور {فرشتہ} نے حیرت انگیز انداز میں کیا؛ اور مانواہ اور اس کی بیوی دیکھ رہے تھے۔\n20۔ کیونکہ جب شعلہ قربان گاہ سے آسمان کی طرف اٹھا، تو خداوند کا فرشتہ قربان گاہ کی آگ میں بلند ہوا۔ اور منوہ اور اس کی بیوی نے اسے دیکھا، اور منہ کے بل زمین پر گر گئے۔\n21. لیکن خداوند کا فرشتہ منوح اور اس کی بیوی کے سامنے مزید ظاہر نہیں ہوا۔ تب منوہ کو معلوم ہوا کہ وہ خداوند کا فرشتہ ہے۔\n22۔ اور منواہ نے اپنی بیوی سے کہا، ہم ضرور مریں گے، کیونکہ ہم نے خدا کو دیکھا ہے۔\n23۔ لیکن اس کی بیوی نے اسے کہا، اگر خداوند ہمیں مارنے پر راضی ہوتا، تو اسے ہمارے ہاتھوں نہ جلنے کی قربانی اور گوشت کی قربانی ملتی، نہ ہی وہ ہمیں یہ سب دکھاتا، اور نہ ہی اس وقت ہمیں ایسی باتیں بتاتا۔\n24۔ اور عورت نے بیٹا پیدا کیا، اور اس کا نام شمشون رکھا: اور بچہ بڑا ہوا، اور خداوند نے اسے برکت دی۔\n25۔ اور خداوند کی روح نے اسے کبھی کبھار دان کے کیمپ میں زورہ اور اشتاول کے درمیان منتقل کرنا شروع کیا۔ {کیمپ...: عبرانی۔ مہانہدان}","1۔ اور شمشون تیمنات گیا، اور تیمنات میں فلسطینیوں کی بیٹیوں کی ایک عورت کو دیکھا۔\n2۔ اور وہ آیا، اپنے والد اور ماں کو بتایا، اور کہا، میں نے تیمنات میں فلسطینیوں کی بیٹیوں کی ایک عورت دیکھی ہے، اب اسے میرے لیے بیوی بنا دو۔\n3۔ پھر اس کے والد اور والدہ نے اس سے کہا، {کیا} تمہارے بھائیوں کی بیٹیوں میں یا میرے تمام لوگوں میں سے کوئی عورت نہیں کہ تم غیر ختنہ شدہ فلسطینیوں کی بیوی لینے جاؤ؟ اور شمشون نے اپنے باپ سے کہا، اسے میرے لیے لے آؤ؛ کیونکہ وہ مجھے خوش کرتی ہے۔ {براہ کرم...: عبرانی۔ یہ میری نظر میں بالکل درست ہے}\n4۔ لیکن اس کے والد اور والدہ کو معلوم نہیں تھا کہ یہ {تھا} خداوند کی طرف سے تھا کہ وہ فلسطینیوں کے خلاف کوئی موقع چاہتا تھا: کیونکہ اس وقت فلسطینیوں کے پاس اسرائیل پر حکمرانی تھی۔\n5۔ پھر شمشون اور اس کے والد اور اس کی ماں تیمناتھ گئے اور تیمنتھ کے انگور کے باغات میں پہنچے: اور دیکھتے ہی ایک نوجوان شیر نے اس کے خلاف دھاڑ ماری۔ {خلاف...: عبرانی اس سے ملنے میں}\n6۔ اور خداوند کی روح اس پر زور سے آئی، اور اس نے اسے ایسے توڑا جیسے وہ بچے کو کرایہ پر لیتا، اور اس کے ہاتھ میں کچھ نہیں تھا: لیکن اس نے اپنے والد یا ماں کو نہیں بتایا کہ اس نے کیا کیا تھا۔\n7۔ اور وہ نیچے گیا، اور عورت سے بات کی؛ اور وہ سیمسن کو بہت خوش کرتی تھی۔\n8۔ اور کچھ دیر بعد وہ اسے لینے واپس آیا، اور وہ شیر کی لاش دیکھنے کے لیے مڑ گیا: اور دیکھو، شیر کی لاش میں شہد اور شہد کا ایک جھنڈ تھا۔\n9۔ اور اس نے اسے اپنے ہاتھوں میں لے لیا، کھانا شروع کر دیا، اور اپنے والد اور والدہ کے پاس آیا، اور انہوں نے انہیں دیا، اور انہوں نے کھایا، لیکن اس نے انہیں نہیں بتایا کہ اس نے شیر کی لاش سے شہد نکالا ہے۔\n10۔ تو اس کا باپ عورت کے پاس نیچے گیا: اور شمشون نے وہاں دعوت کی؛ کیونکہ نوجوانوں نے ایسا ہی کیا۔\n11۔ اور جب انہوں نے اسے دیکھا تو وہ تیس ساتھیوں کو اس کے ساتھ لے آئے۔\n12۔ اور شمشون نے ان سے کہا، اب میں تم سے ایک پہیلی پیش کروں گا: اگر تم یقینا تہوار کے سات دنوں میں مجھے یہ پہیلی بتا دو اور معلوم کر لو، تو میں تمہیں تیس چادریں اور تیس بدلے کے کپڑے دوں گا: {چادریں: یا قمیضیں}\n13۔ لیکن اگر تم مجھے ظاہر نہیں کر سکتے، تو مجھے تیس چادریں اور تیس کپڑوں کے بدلے دے دو۔ اور انہوں نے اس سے کہا، اپنا پہیلی سناؤ، تاکہ ہم سن سکیں۔ {چادریں: یا، شرٹس}\n14۔ اور اس نے ان سے کہا، کھانے والے سے گوشت نکلا، اور طاقتور سے مٹھاس نکلی۔ اور وہ تین دن میں معمہ حل نہیں کر سکے۔\n15۔ اور ساتویں دن ایسا ہوا کہ انہوں نے شمشون کی بیوی سے کہا، اپنے شوہر کو آمادہ کرو تاکہ وہ ہمیں معمہ بتا دے، ورنہ ہم تمہیں اور تمہارے باپ کے گھر کو آگ سے جلا دیں گے: کیا تم نے ہمیں بلایا ہے کہ جو کچھ ہمارے پاس ہے اسے لے لیں؟ {کیا یہ} نہیں ہے {تو}؟ {لے لو...: عببرانی۔ ہم پر قبضہ کر لیں، یا ہمیں غریب کر دیں؟}\n16۔ اور شمشون کی بیوی اس کے سامنے روئی اور کہا، \"تم مجھ سے نفرت کرتے ہو، اور مجھ سے محبت نہیں کرتے: تم نے میری قوم کے بچوں کے لیے ایک پہیلی رکھی ہے، اور مجھے نہیں بتایا۔ اور اس نے اس سے کہا، دیکھو، میں نے اپنے والد یا ماں کو نہیں بتایا، اور کیا میں تمہیں بتاؤں؟\n17۔ اور وہ سات دن اس کے سامنے روتی رہی، جب ان کا جشن جاری رہا: اور ساتویں دن ایسا ہوا کہ اس نے اسے بتایا، کیونکہ وہ اس پر ناراض تھی، اور اس نے اپنی قوم کے بچوں کو پہیلی سنائی۔ {سات...: یا، باقی سات دن}\n18۔ اور شہر کے لوگوں نے ساتویں دن سورج غروب ہونے سے پہلے اس سے کہا، شہد سے زیادہ میٹھا کیا ہے؟ اور شیر سے زیادہ طاقتور کیا ہے؟ اور اس نے ان سے کہا، اگر تم نے میری گائے سے جوتا نہ ہوتا تو تم میرا پہیلی نہ جان پاتے۔\n19۔ اور خداوند کی روح اس پر آئی، اور وہ اشکلون گیا، ان میں سے تیس آدمیوں کو مار ڈالا، ان کی مال غنیمت لے کر انہیں کپڑے بدلے دیے جو معمہ کی وضاحت کرتے تھے۔ اور اس کا غصہ بھڑک اٹھا، اور وہ اپنے والد کے گھر چلا گیا۔ {اسپائل: یا، لباس}\n20۔ لیکن شمشون کی بیوی کو اس کے ساتھی کے حوالے کر دیا گیا، جسے اس نے اپنا دوست بنایا تھا۔","1۔ لیکن کچھ عرصے بعد، گندم کی فصل کے وقت، شمشون اپنی بیوی سے بچے کے ساتھ ملنے آیا؛ اور اس نے کہا، میں اپنی بیوی کے پاس چیمبر میں جاؤں گا۔ لیکن اس کے والد نے اسے اندر جانے کی اجازت نہیں دی۔\n2۔ اور اس کے والد نے کہا، میں واقعی سمجھتا تھا کہ تم اسے مکمل طور پر ناپسند کرتے ہو؛ اسی لیے میں نے اسے تمہارے ساتھی کو دے دیا: کیا اس کی چھوٹی بہن اس سے زیادہ خوبصورت نہیں؟ اسے لے لو، میں تم سے دعا کرتا ہوں، اس کی بجائے۔ {لے لو...: عببرانی۔ اسے اپنا بننے دو}\n3۔ اور شمشون نے ان کے بارے میں کہا، اب میں فلسطینیوں سے زیادہ بے گناہ ہوں گا، چاہے میں انہیں ناراض کروں۔ {مزید...: یا، فلسطینیوں سے بے قصور، وغیرہ}\n4۔ اور شمشون نے تین سو لومڑیاں پکڑیں، اور آگ کے برنڈز کو لے کر دم سے دم گھمایا، اور دو دموں کے درمیان ایک آگ لگا دی۔ {آتش زدہ: یا، مشعل}\n5۔ اور جب اس نے داغوں کو آگ لگا دی، تو اس نے انہیں فلسطینیوں کے کھڑے مکئی میں ڈال دیا، اور جھٹکوں اور کھڑے مکئی کو انگور کے باغات {اور} زیتون کے ساتھ جلا دیا۔\n6۔ پھر فلسطینیوں نے کہا، یہ کس نے کیا؟ اور انہوں نے جواب دیا، شمشون، تیمنی کا داماد، کیونکہ اس نے اپنی بیوی کو لے کر اپنے ساتھی کے حوالے کر دیا تھا۔ اور فلسطینی آئے اور اسے اور اس کے والد کو آگ سے جلا دیا۔\n7۔ اور شمشون نے ان سے کہا، اگرچہ تم نے یہ کیا ہے، پھر بھی میں تم سے بدلہ لوں گا، اور اس کے بعد میں رک جاؤں گا۔\n8۔ اور اس نے ان کے کولہے اور ران پر زبردست قتل عام کیا: اور وہ نیچے جا کر چٹان ایٹم کی چوٹی پر رہا۔\n9۔ پھر فلسطینی اوپر گئے، یہوداہ کو شامل کیا، اور لیہی میں پھیل گئے۔\n10۔ اور یہوداہ کے لوگوں نے کہا، تم ہمارے خلاف کیوں آ رہے ہو؟ اور انہوں نے جواب دیا، \"ہم شمشون کو باندھنے کے لیے آئے ہیں، تاکہ اس کے ساتھ وہی کریں جو اس نے ہمارے ساتھ کیا ہے۔\n11۔ پھر یہوداہ کے تین ہزار آدمی چٹان ایتام کی چوٹی پر گئے اور شمشون سے کہا، کیا تم نہیں جانتے کہ فلسطینی ہمارے حکمران ہیں؟ یہ کیا ہے جو تم نے ہمارے ساتھ کیا ہے؟ اور اس نے ان سے کہا، جیسے انہوں نے میرے ساتھ کیا، ویسے ہی میں نے ان کے ساتھ کیا۔ {گیا: ہیب۔ گر گیا}\n12۔ اور انہوں نے اس سے کہا، ہم تمہیں باندھنے آئے ہیں تاکہ تمہیں فلسطینیوں کے ہاتھ میں دے سکیں۔ اور شمشون نے ان سے کہا، مجھ سے قسم کھاؤ کہ تم خود مجھ پر حملہ نہیں کرو گے۔\n13۔ اور انہوں نے اس سے کہا، نہیں؛ لیکن ہم تمہیں مضبوطی سے باندھ دیں گے، اور تمہیں ان کے ہاتھ میں دے دیں گے: لیکن یقینا ہم تمہیں نہیں ماریں گے۔ اور انہوں نے اسے دو نئی رسیوں سے باندھ دیا، اور اسے چٹان سے اوپر لایا۔\n14۔ {اور} جب وہ لیحی پہنچا، فلسطینیوں نے اس کے خلاف پکارا: اور خداوند کی روح اس پر زور سے آ گئی، اور اس کے بازوؤں پر جو رسیاں {تھیں} وہ آگ سے جلنے والے فِن کی طرح ہو گئیں، اور اس کے ہاتھوں سے اس کے پٹیاں الگ ہو گئیں۔ {ڈھیلا ہوا: ہیب۔ پگھل گئے}\n15۔ اور اس نے ایک نیا گدھے کی ہڈی تلاش کی، اپنا ہاتھ بڑھایا، اسے پکڑ کر اس سے ہزار آدمیوں کو مار ڈالا۔ {نیا: عبرانی۔ نمنا}\n16۔ اور شمشون نے کہا، گدھے کی جبڑے کی ہڈی سے، گدھے کے جبڑے کے ڈھیر سے میں نے ہزار آدمی مارے ہیں۔ {ڈھیر پر ہے...: عبرانی ایک ڈھیر، دو ڈھیر}\n17۔ اور جب اس نے بولنا بند کر دیا، تو اس نے اپنے ہاتھ سے جبڑے کی ہڈی پھینک دی اور اس جگہ کو رمتلہی کہا۔ {رمتلہی: یعنی، جبڑے کی ہڈی کو اٹھانا، یا جبڑے کی ہڈی کو پھینکنا}\n18۔ اور وہ شدید پیاسا تھا، اور خداوند کو پکارا اور کہا، تو نے یہ عظیم نجات اپنے خادم کے ہاتھ میں دی ہے: اور اب میں پیاس سے مر جاؤں گا، اور ختنہ شدہ کے ہاتھ میں گر جاؤں گا؟\n19۔ لیکن خدا نے جبڑے میں ایک کھوکھلا مقام کھولا، اور وہاں سے پانی نکلا؛ اور جب وہ پی چکا تو اس کی روح دوبارہ آ گئی، اور وہ زندہ ہو گیا: اسی لیے اس نے اس کا نام انہاکور رکھا، جو آج تک لیہی میں ہے۔ {ان ہاکور: یعنی اس کا کنواں جس نے پکارا یا، پکارا} {جبڑا: یا، لیہی، جیسا کہ اس باب میں کہا گیا ہے}\n20۔ اور اس نے فلسطینیوں کے زمانے میں بیس سال اسرائیل کا فیصلہ کیا۔","1۔ پھر شمشون غزہ گیا، وہاں ایک طوائف کو دیکھا، اور اس کے پاس گیا۔ {: عبرانی۔ ایک عورت، ایک طوائف}\n2۔ {اور کہا گیا} غازی نے کہا، شمشون یہاں آیا ہے۔ اور انہوں نے اسے گھیر لیا، اور ساری رات شہر کے دروازے پر اس کا انتظار کیا، اور ساری رات خاموش رہے، کہتے ہوئے، صبح جب دن ہوگا، ہم اسے مار ڈالیں گے۔ {خاموش: عبرانی۔ خاموشی}\n3۔ اور شمشون آدھی رات تک لیٹا رہا، آدھی رات کو اٹھا، شہر کے دروازے اور دونوں ستونوں کو لے کر چلا گیا، سب کچھ بھی، اور انہیں اپنے کندھوں پر ڈال کر ایک پہاڑی کی چوٹی تک لے گیا جو {ہیبرون} کے سامنے ہے۔ {بار...: عبدی۔ بار کے ساتھ}\n4۔ اور بعد میں ہوا کہ وہ وادی سورک میں ایک عورت سے محبت کرتا تھا، جس کا نام {تھا} دلیلہ تھا۔ {میں...: یا، ندی کے کنارے}\n5۔ اور فلسطینیوں کے سردار اس کے پاس آئے اور کہا، اسے بہکا دو، اور دیکھو کہ اس کی بڑی طاقت کہاں ہے، اور ہم کس طرح اس پر غالب آ سکتے ہیں، تاکہ ہم اسے تکلیف دینے پر مجبور کر سکیں: اور ہم تمہیں ہم میں سے ہر ایک کو گیارہ سو چاندی کے ٹکڑے دیں گے۔ {مصیبت: یا، عاجز}\n6۔ اور دلیلہ نے سیمسن سے کہا، بتاؤ، میں دعا کرتا ہوں، کہ تمہاری عظیم طاقت کہاں ہے، اور کس سے تم تمہیں تکلیف دے سکتے ہو۔\n7۔ اور شمشون نے اس سے کہا، اگر وہ مجھے سات سبز پھولوں سے باندھ دیں جو کبھی خشک نہیں ہوئے، تو میں کمزور ہوں گا، اور دوسرے انسان کی طرح ہوں گا۔ {سبز...: یا، نئے رسے: عبرانی۔ moist} {ایک اور: عبرانی۔ ایک}\n8۔ پھر فلسطینیوں کے سردار اس کے پاس سات سبز کپڑے لے آئے جو خشک نہیں ہوئے تھے، اور اس نے اسے ان سے باندھ دیا۔ {سبز...: یا، نئے تاریں: عبرانی۔ نمنا}\n9۔ اب {وہاں} لوگ انتظار میں بیٹھے تھے، جو اس کے ساتھ کمرے میں ٹھہرے ہوئے تھے۔ اور اس نے اس سے کہا، فلسطینی لوگ تمہارے اوپر ہوں، شمشن۔ اور وہ وڈز کو توڑ دیتا ہے، جیسے ایک دھاگہ آگ کو چھونے پر ٹوٹ جاتا ہے۔ اس لیے اس کی طاقت معلوم نہیں تھی۔ {چھونا: عبرانی۔ خوشبو}\n10۔ اور دلیلہ نے شمشون سے کہا، دیکھو، تم نے میرا مذاق اڑایا اور جھوٹ بولا: اب بتاؤ، میں تم سے دعا کرتا ہوں، کہ تم کس کے ساتھ بندھن میں ہو۔\n11۔ اور اس نے اس سے کہا، اگر وہ مجھے نئی رسیوں سے باندھ دیں جو کبھی استعمال نہیں ہوئیں، تو میں کمزور ہو جاؤں گا، اور دوسرے انسان کی طرح رہوں گا۔ {جو کبھی نہیں...: عبرانی۔ جس پر کام نہیں ہوا}\n12۔ لہٰذا دلیلہ نے نئی رسی لی، اسے باندھا، اور اسے کہا، فلستیوں نے تم پر آؤ، شمشن۔ اور {وہاں} جھوٹے لوگ کمرے میں موجود تھے۔ اور اس نے انہیں اپنے بازوؤں سے دھاگے کی طرح توڑ دیا۔\n13۔ اور دلیلہ نے شمشون سے کہا، اب تک تم نے میرا مذاق اڑایا اور جھوٹ بولا: مجھے بتاؤ کہ تم کس چیز سے بندھ سکتے ہو۔ اور اس نے اس سے کہا، اگر تم میرے سر کے سات بالوں کو جال سے بناؤ۔\n14۔ اور اس نے اسے پن سے باندھا اور اس سے کہا، فلسطینی لوگ تمہارے اوپر ہوں، شمشن۔ اور وہ نیند سے جاگا، اور بیم کے پن اور جال کے ساتھ چلا گیا۔\n15۔ اور اس نے اس سے کہا، تم کیسے کہہ سکتے ہو، میں تم سے محبت کرتی ہوں، جب تمہارا دل میرے ساتھ نہیں ہے؟ تم نے تین بار میرا مذاق اڑایا ہے، اور مجھے نہیں بتایا کہ تمہاری بڑی طاقت کہاں ہے۔\n16۔ اور ایسا ہوا، جب وہ روزانہ اپنے الفاظ سے اس پر زور دیتی اور اصرار کرتی، {اتنی} کہ اس کی روح موت تک پریشان ہو گئی؛ {ناراض: عبرانی۔ مختصر شدہ}\n17۔ کہ اس نے اسے اپنا پورا دل بتا دیا، اور کہا، میرے سر پر کوئی ریزر نہیں آیا؛ کیونکہ میں اپنی ماں کے پیٹ سے خدا کے لیے ناصری رہا ہوں: اگر میں منڈوا گیا تو میری طاقت ختم ہو جائے گی، اور میں کمزور ہو جاؤں گا، اور کسی بھی {دوسرے} انسان کی طرح ہو جاؤں گا۔\n18۔ اور جب دلیلہ نے دیکھا کہ اس نے اسے اپنا سارا دل بتا دیا ہے، تو اس نے فلسطینیوں کے سرداروں کو بلایا اور کہا، اس بار اوپر آؤ، کیونکہ اس نے مجھے اپنا سارا دل دکھا دیا ہے۔ پھر فلسطینیوں کے سردار اس کے پاس آئے اور اپنے ہاتھ میں پیسے لے آئے۔\n19۔ اور اس نے اسے گھٹنوں کے بل سلایا؛ اور اس نے ایک آدمی کو بلایا، اور اس نے اس کے سر کے سات بال منڈوا دیے؛ اور اس نے اسے تکلیف دینا شروع کر دی، اور اس کی طاقت ختم ہو گئی۔\n20۔ اور اس نے کہا، فلسطینی تم پر آؤ، شمشن۔ اور وہ اپنی نیند سے جاگ گیا، اور کہا، میں پہلے کی طرح باہر جاؤں گا اور خود کو جھنجھوڑوں گا۔ اور وہ نہیں جانتا تھا کہ خداوند اس سے جدا ہو گیا ہے۔\n21۔ لیکن فلسطینیوں نے اسے لے لیا، اس کی آنکھیں نکال دیں، غزہ لے آئے، اور پیتل کی زنجیروں سے باندھ دیا؛ اور وہ واقعی جیل میں محنت کرتا تھا۔ {آؤٹ آؤٹ: ہیب۔ بور ہو چکا ہوں}\n22۔ تاہم، شیو کے بعد اس کے سر کے بال دوبارہ بڑھنے لگے۔ {بعد...: یا، جیسے جب وہ شیو کیا گیا تھا}\n23۔ پھر فلسطینیوں کے سرداروں نے انہیں جمع کیا تاکہ وہ اپنے خدا داگون کو بڑی قربانی دیں اور خوش ہوں: کیونکہ انہوں نے کہا، ہمارے خدا نے ہمارے دشمن شمشون کو ہمارے ہاتھ میں دے دیا ہے۔\n24۔ اور جب لوگوں نے اسے دیکھا، تو انہوں نے اپنے خدا کی تعریف کی: کیونکہ انہوں نے کہا، ہمارے خدا نے ہمارے دشمن اور ہمارے ملک کے تباہ کن کو ہمارے ہاتھوں میں دے دیا ہے، جس نے ہم میں سے بہت سے کو مار ڈالا۔ {جو کہ...: عبرانی اور جس نے ہمارے مارے گئے لوگوں کو بڑھایا}\n25۔ اور جب ان کے دل خوش تھے، تو انہوں نے کہا، شمشون کو بلاؤ، تاکہ وہ ہمیں خوش کرے۔ اور انہوں نے شمشون کو قید خانے سے باہر بلایا؛ اور اس نے انہیں کھیل بنایا: اور اسے ستونوں کے درمیان رکھ دیا۔ {وہ: عبرانی۔ ان سے پہلے}\n26۔ اور شمشون نے اس لڑکے سے کہا جس نے اس کا ہاتھ پکڑا ہوا تھا، \"مجھے اجازت دو تاکہ میں ان ستونوں کو محسوس کر سکوں جن پر گھر کھڑا ہے، تاکہ میں ان پر ٹیک لگا سکوں۔\n27۔ اب گھر مردوں اور عورتوں سے بھرا ہوا تھا؛ اور فلسطینیوں کے تمام سردار وہاں موجود تھے؛ اور چھت پر تقریبا تین ہزار مرد اور عورتیں موجود تھے، جو دیکھ رہے تھے جب شمشون کھیل رہا تھا۔\n28۔ اور شمشون نے خداوند کو پکارا اور کہا، اے خداوند خدا، مجھے یاد فرما، میں تجھ سے دعا کرتا ہوں اور مجھے مضبوط فرما، میں تجھ سے دعا کرتا ہوں، صرف اس بار، اے خدا، تاکہ میں اپنی دونوں آنکھوں کے لیے فلسطینیوں کا فورا بدلہ لے سکوں۔\n29۔ اور شمشون نے ان دو درمیانی ستونوں کو پکڑ لیا جن پر گھر کھڑا تھا، جن پر وہ کھڑا تھا، ایک کے دائیں ہاتھ سے اور دوسرے کے بائیں ہاتھ سے۔ {جس پر...: یا، وہ ان پر ٹیک لگاتا تھا}\n30۔ اور شمشون نے کہا، مجھے فلسطینیوں کے ساتھ مرنے دو۔ اور اس نے اپنی پوری طاقت سے جھک کر سلام کیا؛ اور یہ گھر لارڈز اور اس میں موجود تمام لوگوں پر گر گیا۔ تو وہ مردہ جو اس نے اپنی موت کے وقت مارے، وہ ان سے زیادہ تھے جنہیں اس نے اپنی زندگی میں مارا۔ {میں: عبرانی۔ میری روح}\n31۔ پھر اس کے بھائی اور اس کے والد کے سارے گھرانے نیچے آئے، اسے لے گئے، اوپر لے آئے اور زورہ اور اشتاول کے درمیان اس کے والد کی تدفین میں دفن کر دیا۔ اور اس نے اسرائیل کو بیس سال کی سزا دی۔","1۔ اور ایک آدمی کوہ افرائیم کا تھا، جس کا نام {تھا} میکاہ۔\n2۔ اور اس نے اپنی ماں سے کہا، وہ گیارہ سو شیکل چاندی جو تم سے لی گئی، جس پر تم نے لعنت بھیجی اور میرے کانوں میں بھی اس کی بات کی، دیکھو، چاندی میرے پاس ہے؛ میں نے لے لیا۔ اور اس کی ماں نے کہا، خداوند کی طرف سے مبارک ہو، میرے بیٹے۔\n3۔ اور جب اس نے اپنی ماں کو گیارہ سو شیکل چاندی واپس کی، تو اس کی ماں نے کہا، میں نے اپنے بیٹے کے لیے مکمل چاندی خداوند کے نام وقف کر دی تھی، تاکہ ایک کندہ شدہ مجسمہ اور پگھلا ہوا مجسمہ بنایا جا سکے: اب میں اسے تمہیں واپس کروں گی۔\n4۔ پھر بھی اس نے یہ رقم اپنی والدہ کو واپس کر دی؛ اور اس کی ماں نے دو سو {شیکل} چاندی لی، اور بانی کو دے دیے، جس نے اس سے ایک کندہ شدہ مجسمہ اور ایک پگھلا ہوا مجسمہ بنایا: اور وہ میکاہ کے گھر میں تھے۔\n5۔ اور میکاہ کے پاس دیوتاؤں کا گھر تھا، اس نے ایک ایفود اور ترافیم بنایا، اور اپنے ایک بیٹے کو مقدس کیا، جو اس کا پادری بن گیا۔ {تقدیس: عبرانی۔ ہاتھ بھر دیا}\n6۔ ان دنوں اسرائیل میں کوئی بادشاہ نہیں تھا، {لیکن} ہر انسان اپنی آنکھوں میں وہی کرتا تھا جو تھا۔\n7۔ اور بیت لحم یہودہ سے ایک نوجوان تھا جو یہوداہ خاندان سے تعلق رکھتا تھا، جو لاوی تھا، اور وہاں ٹھہرا۔\n8۔ اور وہ آدمی بیت اللحم یہودہ سے شہر سے نکل کر ٹھہرا تاکہ وہاں ٹھہرے: اور سفر کے دوران وہ ایفریم پر سوار ہو کر میکاہ کے گھر پہنچا۔ {جیسا کہ وہ...: عبرانی۔ اپنی راہ بنانے میں}\n9۔ اور میکاہ نے اس سے کہا، تم کہاں سے آئے ہو؟ اور اس نے اس سے کہا، میں بیت اللحم یہودہ کا لاوی ہوں، اور میں قیام کے لیے جاتا ہوں جہاں مجھے {کوئی جگہ} مل جائے۔\n10۔ اور میخا نے اس سے کہا، میرے ساتھ رہو، اور میرے لیے باپ اور کاہن بنو، اور میں تمہیں سالانہ دس شیکل چاندی اور ایک لباس اور تمہاری خوراک دوں گا۔ تو لاوی اندر چلا گیا۔ {ایک سوٹ...: یا، ایک ڈبل سوٹ وغیرہ: عبرانی۔ ایک آرڈر آف گارمنٹس}\n11۔ اور لاوی اس آدمی کے ساتھ رہنے پر راضی تھا؛ اور نوجوان اس کے لیے اس کے بیٹوں میں سے ایک تھا۔\n12۔ اور میکاہ نے لاویوں کو مقدس قرار دیا؛ اور نوجوان اس کا پادری بن گیا، اور میکاہ کے گھر میں تھا۔\n13۔ پھر میکاہ نے کہا، اب میں جانتا ہوں کہ خداوند میرے لیے اچھا کرے گا، کیونکہ میرے پاس ایک لاوی ہے جو میرا پادری ہے۔","1۔ ان دنوں اسرائیل میں کوئی بادشاہ نہیں تھا: اور ان دنوں ڈینیوں کے قبیلے نے ان کے لیے وراثت تلاش کی؛ کیونکہ آج تک {ان کی} کی ساری میراث اسرائیل کے قبائل میں ان کے پاس نہیں آئی تھی۔\n2۔ اور دان کے بچوں نے اپنے خاندان سے اپنے ساحلوں سے پانچ آدمی بھیجے، بہادر لوگ، زورہ اور اشتاول سے، تاکہ زمین کی جاسوسی کریں اور اس کی تلاش کریں؛ اور انہوں نے ان سے کہا، جاؤ، زمین کی تلاشی لو: جب وہ افرائیم کے پہاڑ کے پاس مائیکا کے گھر آئے تو وہاں ٹھہرے۔ {مرد حضرات: عبرانی۔ سنز آف}\n3۔ جب وہ میکاہ کے گھر کے پاس پہنچے، تو انہوں نے نوجوان لاوی کی آواز جان لی، اور وہاں مڑے اور اس سے کہا، تمہیں یہاں کون لایا؟ اور تم اس {جگہ} میں کیا بناتے ہو؟ اور یہاں کیا ہے؟\n4۔ اور اس نے ان سے کہا، اس طرح میکاہ نے میرے ساتھ معاملہ کیا، اور مجھے ملازمت دی، اور میں اس کا پادری ہوں۔\n5۔ اور انہوں نے اس سے کہا، ہم خدا سے دعا کرتے ہیں کہ ہم جان سکیں کہ ہمارا راستہ کامیاب ہوگا یا نہیں۔\n6۔ اور پادری نے ان سے کہا، امن سے جاؤ: خداوند کے سامنے تمہارا راستہ ہے جہاں تم جاتے ہو۔\n7۔ پھر پانچوں آدمی روانہ ہوئے، اور لیش پہنچے، اور وہاں موجود لوگوں کو دیکھا کہ وہ زیدونیوں کی طرح بے پرواہ اور محفوظ رہتے ہیں؛ اور {زمین میں} کوئی مجسٹریٹ نہیں تھا جو {ان} کو {کسی بھی} چیز پر شرمندہ کر دے؛ اور وہ زیدونیوں سے بہت دور تھے، اور ان کا کسی انسان سے کوئی تعلق نہیں تھا۔ {لیش: جسے لیشم بھی کہا جاتا ہے} {مجسٹریٹ: عبرانی۔ پابندیوں کا مالک، یا وارث}\n8۔ اور وہ اپنے بھائیوں کے پاس زورہ اور اشتاول آئے: اور ان کے بھائیوں نے ان سے کہا، تم کیا کہتے ہو؟\n9۔ اور انہوں نے کہا، اٹھو، تاکہ ہم ان کے خلاف جا سکیں: کیونکہ ہم نے زمین دیکھی ہے، اور دیکھو، وہ بہت اچھی ہے، اور کیا تم ابھی بھی ہو؟ جانے میں سستی نہ کریں، {اور} زمین پر قبضہ کرنے کے لیے داخل نہ ہوں۔\n10۔ جب تم جاؤ گے، تو تم ایک محفوظ قوم کے پاس آؤ گے، اور ایک وسیع زمین پر: کیونکہ خدا نے اسے تمہارے ہاتھوں میں دیا ہے؛ ایک ایسی جگہ جہاں {زمین میں کسی چیز کی کمی نہیں}۔\n11۔ اور وہاں سے دانیوں کے خاندان، زورہ سے اور اشتاول سے، چھ سو آدمی جنگی ہتھیار لے کر روانہ ہوئے۔ {مقرر: عبرانی بند}\n12۔ اور وہ اوپر گئے اور یہوداہ کے کیرجاتجیاریم میں زمین باڑی کی: اسی لیے انہوں نے آج تک اس جگہ کو مہانہدان کہا: دیکھو، یہ کیرجاتجاریم کے پیچھے ہے۔\n13۔ اور وہ وہاں سے کوہ افرائیم کی طرف گئے، اور میکاہ کے گھر پہنچے۔\n14۔ پھر پانچ آدمیوں نے جواب دیا جو لیش کے ملک کی جاسوسی کے لیے گئے تھے، اور اپنے بھائیوں سے کہا، کیا تم جانتے ہو کہ ان گھروں میں ایک ایفود، تیرافیم، اور ایک کندہ شدہ مورت، اور ایک پگھلا ہوا مجسمہ ہے؟ اب غور کرو کہ تمہیں کیا کرنا ہے۔\n15۔ اور وہ وہاں مڑے، اور نوجوان لاوی کے گھر آئے، حتیٰ کہ میکاہ کے گھر بھی، اور اسے سلام کیا۔ {سلام...: عببری۔ اس سے امن مانگا تھا}\n16۔ اور چھ سو آدمی جو اپنے جنگی ہتھیاروں کے ساتھ مقرر کیے گئے تھے، جو دان کے بچوں کے تھے، دروازے کے دروازے کے دروازے کے پاس کھڑے تھے۔\n17۔ اور وہ پانچ آدمی جو زمین کی جاسوسی کے لیے گئے تھے، اوپر گئے، {اور} وہاں آئے، {اور} کندہ شدہ مورت، ایفود، ترافیم اور پگھلا ہوا مجسمہ لے گئے: اور پادری دروازے کے داخلے میں کھڑا تھا، چھ سو آدمیوں کے ساتھ جو جنگی ہتھیار لیے گئے تھے۔\n18۔ اور یہ میکاہ کے گھر گئے، اور کندہ شدہ مورت، ایفود، ترافیم اور پگھلا ہوا مجسمہ لے آئے۔ پھر پادری نے ان سے کہا، تم کیا چاہتے ہو؟\n19۔ اور انہوں نے اس سے کہا، خاموش رہو، اپنا ہاتھ اپنے منہ پر رکھو، اور ہمارے ساتھ چلو، اور ہمارے لیے باپ اور پادری بنو: کیا تمہارے لیے بہتر ہے کہ تم ایک آدمی کے گھر کے پادری بنو، یا اسرائیل میں کسی قبیلے اور خاندان کے پادر؟\n20۔ اور پادری کا دل خوش ہوا، اس نے ایفود، ترافیم، اور کندہ شدہ مجسمہ لے کر لوگوں کے درمیان چلا گیا۔\n21۔ تو وہ مڑے اور روانہ ہو گئے، اور چھوٹے، مویشی اور گاڑی کو اپنے سامنے رکھ دیا۔\n22۔ {اور} جب وہ میکاہ کے گھر سے کافی دور تھے، تو میکاہ کے گھر کے قریب کے گھروں میں موجود مرد جمع ہو گئے اور دان کے بچوں کو پکڑ لیا۔\n23۔ اور انہوں نے دان کے بچوں کو پکارا۔ اور انہوں نے منہ موڑ کر میکاہ سے کہا، تمہیں کیا ہوا ہے کہ تم ایسی جماعت کے ساتھ آتے ہو؟ {comest...: عبوری۔ آرٹ اکٹھا کیا گیا؟}\n24۔ اور اس نے کہا، تم نے میرے بنائے ہوئے خدا اور پادری کو چھین لیا ہے، اور تم چلے گئے ہو: اور میرے پاس اور کیا ہے؟ اور یہ کیا ہے جو تم مجھ سے کہتے ہو، تمہیں کیا ہو گیا ہے؟\n25۔ اور دان کے بچوں نے اس سے کہا، \"تمہاری آواز ہمارے درمیان نہ سنی جائے، ورنہ غصے والے لوگ تم پر دوڑ پڑیں گے، اور تم اپنی جان کھو دو گے، اپنے گھرانے کی جانوں کے ساتھ۔ {غصے میں: عبرانی۔ روح کی کڑوا}\n26۔ اور دان کے بچے اپنے راستے پر چلے گئے: اور جب میکاہ نے دیکھا کہ وہ اس کے لیے بہت طاقتور ہیں، تو وہ مڑا اور اپنے گھر واپس چلا گیا۔\n27۔ اور انہوں نے وہ چیزیں لے لیں جو میکاہ نے بنائی تھیں، اور اس کے پاس جو پادری تھا، اور لیش آئے، ایک ایسے لوگوں کے پاس جو پرسکون اور مطمئن تھے: اور انہیں تلوار کے نوک سے مارا اور شہر کو آگ سے جلا دیا۔\n28۔ اور کوئی نجات دہندہ نہیں تھا، کیونکہ وہ زیدون سے دور تھا، اور ان کا کسی بھی آدمی سے کوئی تعلق نہیں تھا؛ اور یہ وادی میں تھا جہاں بیت ہرحوب نے {لیتھ} کیا۔ اور انہوں نے ایک شہر بنایا، اور وہاں بسے۔\n29۔ اور انہوں نے شہر کا نام دان رکھا، جو ان کے والد دان کے نام پر تھا، جو اسرائیل میں پیدا ہوا تھا: اگرچہ شہر کا نام شروع میں لیش تھا۔\n30۔ اور دان کے بچوں نے مجسمہ نصب کیا: اور یوناتھن، گرشوم کا بیٹا، منسی کا بیٹا، وہ اور اس کے بیٹے دان قبیلے کے کاہن رہے، یہاں تک کہ زمین کی قید کے دن تک۔\n31۔ اور انہوں نے انہیں میکاہ کی کندہ شدہ تصویر تیار کی، جو اس نے بنائی تھی، جب تک کہ خدا کا گھر شیلوہ میں تھا۔","1۔ اور ان دنوں ایسا ہوا، جب اسرائیل میں کوئی بادشاہ نہیں تھا، کہ ایک لاوی پہاڑ افرائیم کے کنارے ٹھہرا ہوا تھا، جس نے بیت اللحم یہودہ سے ایک کنیز کو اپنے پاس لے لیا۔ {ایک کنیز: عبرانی۔ عورت، کنیز، یا بیوی، کنیز}\n2۔ اور اس کی محبوبہ نے اس کے خلاف طوائف کو کھیلا، اور اس سے دور اپنے والد کے گھر بیت لحم یہودا چلی گئی، اور وہاں چار مہینے مکمل رہی۔ {چار پورے مہینے: یا، ایک سال اور چار ماہ: عبرانی۔ دن، چار مہینے}\n3۔ اور اس کا شوہر اٹھا، اور اس کے پیچھے گیا، اس سے دوستانہ بات کرنے کے لیے، {اور} اسے دوبارہ لے آیا، اپنے نوکر کو ساتھ لے کر، اور چند گدھے بھی، اور وہ اسے اپنے والد کے گھر لے آئی: اور جب دوشیزہ کے والد نے اسے دیکھا تو وہ خوش ہوا۔ {دوستانہ...: عبرانی۔ اس کے دل سے}\n4۔ اور اس کے سسر، جو دوشیزہ کے والد تھے، نے اسے اپنے پاس رکھا؛ اور وہ تین دن اس کے ساتھ رہا: تو وہ کھایا، پیا اور وہاں ٹھہرے۔\n5۔ اور چوتھے دن، جب وہ صبح سویرے اٹھے، وہ روانہ ہونے کے لیے اٹھا: اور دوشیزہ کے والد نے اپنے داماد سے کہا، اپنے دل کو روٹی کے ایک ٹکڑے سے تسلی دو، اور پھر اپنی راہ پر چلے جاؤ۔ {آرام: عبرانی۔ مضبوط کریں}\n6۔ اور وہ دونوں بیٹھ گئے، اور دونوں کو ایک ساتھ کھایا اور پیا: کیونکہ دوشیزہ کے باپ نے اس آدمی سے کہا تھا، میں دعا کرتا ہوں کہ خوش ہو جاؤ، اور ساری رات ٹھہرو، اور اپنا دل خوش رکھو۔\n7۔ اور جب وہ آدمی روانہ ہونے کے لیے اٹھا، اس کے سسر نے اسے اصرار کیا: اس لیے وہ دوبارہ وہاں ٹھہر گیا۔\n8۔ اور وہ پانچویں دن صبح سویرے اٹھا تاکہ روانہ ہو سکے: اور دوشیزہ کے والد نے کہا، اپنے دل کو تسلی دے، میں دعا کرتا ہوں۔ اور وہ دوپہر تک رکے رہے، اور دونوں کھا گئے۔ {دوپہر تک: عبرانی۔ جب تک دن ختم نہ ہو گیا}\n9۔ اور جب وہ آدمی روانہ ہونے کے لیے اٹھا، وہ، اس کی محبوبہ اور اس کا خادم، اس کا سسر، دوشیزہ کا باپ، اس سے کہا، دیکھو، اب دن شام کی طرف بڑھ رہا ہے، میں تم سے دعا کرتا ہوں کہ تم ساری رات ٹھہرے: دیکھو، دن ختم ہونے کو ہے، یہاں ٹھہر جاؤ، تاکہ تمہارا دل خوش رہے؛ اور کل تمہیں جلدی روانہ کرو تاکہ تم گھر جا سکو۔ {ڈرائنگ: عبوری۔ کمزور ہے} {دن ختم ہونے کو بڑھتا ہے: عبرانی۔ یہ دن کا پچنگ کا وقت ہے} {گھر: عبرانی۔ اپنے خیمے کی طرف}\n10۔ لیکن وہ آدمی اس رات رکنے کو تیار نہیں تھا، بلکہ اٹھا اور چلا گیا، اور یبوس کے خلاف آ گیا، جو {ہے} یروشلم؛ اور اس کے ساتھ دو گدھے زین لگے ہوئے تھے، اس کی محبوبہ بھی اس کے ساتھ تھی۔ {مخالف: عبرانی اوور اوینسٹ}\n11۔ {اور} جب وہ یبوس کے ہاتھوں {تھے} تو دن بہت گزر چکا تھا؛ اور خادم نے اپنے مالک سے کہا، آؤ، میں تم سے دعا کرتا ہوں، اور ہم اس یبوسائیوں کے شہر میں داخل ہو جائیں اور وہاں ٹھہریں۔\n12۔ اور اس کے آقا نے اس سے کہا، ہم یہاں کسی اجنبی کے شہر میں نہیں جائیں گے، جو بنی اسرائیل کا نہ ہو؛ ہم گبعیہ کے پاس جائیں گے۔\n13۔ اور اس نے اپنے خادم سے کہا، آؤ، اور ہم ان جگہوں میں سے کسی ایک کے قریب جا کر رات بھر قیام کریں، گبعیہ یا رامہ میں۔\n14۔ اور وہ چلے گئے اور اپنی راہ پر چلے گئے؛ اور سورج ان پر غروب ہوا {جب وہ تھے} گبعہ کے ذریعے، جو {بنیامن کا ہے}۔\n15۔ اور وہ وہاں سے مڑ گئے، تاکہ گبعیہ میں ٹھہریں: اور جب وہ اندر گیا تو اسے شہر کی ایک گلی میں بٹھا دیا، کیونکہ کوئی آدمی انہیں اپنے گھر میں رہائش کے لیے نہیں لے گیا۔\n16۔ اور دیکھو، ایک بوڑھا آدمی اپنے کام سے کھیت سے باہر آیا، جو {تھا} پہاڑ افرائیم کا؛ اور وہ گبعیہ میں ٹھہرا: لیکن اس جگہ کے لوگ {تھے} بنیمی تھے۔\n17۔ اور جب اس نے اپنی آنکھیں اٹھائیں، تو اس نے شہر کی گلی میں ایک آوارہ آدمی کو دیکھا: اور بوڑھے آدمی نے کہا، کہاں جا رہے ہو؟ اور تم کہاں سے آئے ہو؟\n18۔ اور اس نے اس سے کہا، ہم بیت اللحم یہودہ سے کوہ افرائیم کے کنارے کی طرف جا رہے ہیں؛ وہاں سے {am} میں: اور میں بیت لحم جودا گیا، لیکن میں {اب} خداوند کے گھر جا رہا ہوں؛ اور کوئی مرد نہیں ہے جو مجھے گھر تک لے جائے۔ {وصول کریں: عبرانی۔ جمع کرو}\n19۔ پھر بھی ہمارے گدھے کے لیے تنکا اور ثبوت دونوں موجود ہیں؛ اور میرے لیے روٹی اور شراب بھی ہے، اور تمہاری خادمہ کے لیے، اور اس نوجوان کے لیے جو تمہارے خادموں کے ساتھ ہے: کسی چیز کی کمی نہیں۔\n20۔ اور بوڑھے آدمی نے کہا، تم پر سلامتی ہو؛ چاہے تیری ساری خواہشات مجھ پر آ جائیں؛ صرف لاڈ، سڑک پر نہیں۔\n21۔ تو وہ اسے اپنے گھر لے آیا، اور گدھوں کو پروونڈر دیا، اور انہوں نے اپنے پاؤں دھوئے، کھایا اور پیا۔\n22. {اب} جب وہ اپنے دلوں کو خوش کر رہے تھے، دیکھو، شہر کے لوگ، بیلیال کے کچھ بیٹے، گھر کے ارد گرد گھیر گئے، {اور} دروازے پر دستک دی، اور گھر کے مالک، بوڑھے آدمی سے کہا، 'اس آدمی کو لے آؤ جو تمہارے گھر میں آیا ہے، تاکہ ہم اسے جان سکیں۔\n23۔ اور وہ آدمی، جو گھر کا مالک تھا، ان کے پاس گیا اور کہا، نہیں، میرے بھائیو، {نہیں}، میں تم سے درخواست کرتا ہوں، اتنی بد نیت نہ کرو؛ جب یہ آدمی میرے گھر میں آیا ہے، تو یہ حماقت نہ کرو۔\n24۔ دیکھو، {یہاں} میری بیٹی ایک کنواری ہے، اور اس کی محبوبہ بھی؛ اب میں انہیں نکالوں گا، اور تم انہیں عاجز کروں گا، اور ان کے ساتھ وہ کروں گا جو تمہیں اچھا لگے: لیکن اس آدمی کے لیے اتنا برا کام نہ کرو۔ {کتنا گھناؤنا...: عبرانی۔ اس حماقت کا معاملہ}\n25۔ لیکن مردوں نے اس کی بات نہیں مانی، تو اس آدمی نے اپنی کنیز کو لے کر ان کے پاس لے آیا؛ اور وہ اسے جانتے تھے، اور ساری رات صبح تک اس پر ظلم کرتے رہے: اور جب دن نکلنے لگا، تو اسے جانے دیا۔\n26۔ پھر وہ عورت صبح سویرے آئی، اور اس مرد کے گھر کے دروازے پر گر گئی جہاں اس کا مالک تھا، یہاں تک کہ روشنی ہو گئی۔\n27۔ اور اس کا سردار صبح اٹھا، گھر کے دروازے کھولے، اور اپنے راستے پر نکل آیا: اور دیکھتے ہی اس کی محبوبہ گھر کے دروازے پر گر گئی، اور اس کے ہاتھ دروازے پر تھے۔\n28۔ اور اس نے اس سے کہا، اوپر، اور چلیں۔ لیکن کسی نے جواب نہیں دیا۔ پھر آدمی نے اسے گدھے پر اٹھایا، اور آدمی اٹھ کھڑا ہوا اور اسے اس کی جگہ لے آیا۔\n29۔ اور جب وہ اپنے گھر میں آیا، اس نے چاقو لیا، اپنی کنیز کو پکڑ لیا، اور اسے اس کی ہڈیوں کے ساتھ بارہ ٹکڑوں میں تقسیم کر دیا، اور اسے اسرائیل کے تمام ساحلوں میں بھیج دیا۔\n30۔ اور ایسا ہوا کہ جو بھی اسے دیکھ رہا تھا وہ کہہ رہا تھا، جب سے بنی اسرائیل مصر کی سرزمین سے نکلے، ایسا کوئی عمل نہیں ہوا اور نہ ہی دیکھا گیا: اس پر غور کرو، نصیحت کرو، اور اپنے دل کی بات کرو۔","1۔ پھر تمام بنی اسرائیل باہر نکل گئے، اور جماعت ایک آدمی کی صورت میں جمع ہو گئی، دان سے بئر شبع تک، گلعاد کی زمین کے ساتھ، پھر مزپے میں خداوند تک۔\n2۔ اور تمام قوم کے سردار، {حتیٰ کہ} اسرائیل کے تمام قبائل میں بھی، خدا کی قوم کی مجلس میں چار لاکھ پیادہ تلوار نکالنے والے سامنے آئے۔\n3۔ (اب بنیامین کے بچوں نے سنا کہ بنی اسرائیل مزپے جا چکے ہیں۔) پھر بنی اسرائیل نے کہا، ہمیں بتاؤ، یہ برائی کیسی تھی؟\n4۔ اور لاوی، جو اس عورت کا شوہر تھا جو ماری گئی تھی، جواب دیا اور کہا، میں اور میری کنیز کے بنیامین کے گبیاہ میں آیا ہوں۔ {دی لیوی: عبرانی۔ وہ آدمی جو لاوی ہے}\n5۔ اور گبعہ کے لوگ میرے خلاف اٹھ کھڑے ہوئے، اور رات کو میرے ارد گرد گھر کو گھیر لیا، {اور} سمجھا کہ انہوں نے مجھے مار ڈالا: اور میری کنیز کو مجبور کیا کہ وہ مر چکی ہے۔ {زبردستی: عبرانی۔ عاجز}\n6۔ اور میں نے اپنی کنیز کو لیا، اسے ٹکڑے ٹکڑے کر دیا، اور اسے اسرائیل کی وراثت کے پورے ملک میں بھیجا، کیونکہ انہوں نے اسرائیل میں بے حیائی اور حماقت کی ہے۔\n7۔ دیکھو، تم سب بنی اسرائیل ہو؛ یہاں اپنا مشورہ اور مشورہ دیں۔\n8۔ اور سب لوگ ایک آدمی بن کر اٹھے اور کہا، ہم میں سے کوئی بھی اس کے خیمے میں نہیں جائے گا، نہ ہی ہم میں سے کوئی اس کے گھر میں جائے گا۔\n9. لیکن اب یہ وہ کام ہوگا جو ہم گبعہ کے ساتھ کریں گے؛ {ہم اس کے خلاف قرعہ اندازی کریں گے}؛\n10۔ اور ہم اسرائیل کے تمام قبائل میں سو کے دس آدمیوں کو اور ہزاروں میں سے ایک سو اور دس ہزار میں سے ایک ہزار کو لوگوں کے لیے خوراک لانے کے لیے لے جائیں گے، تاکہ جب وہ گبعہ بنیامین کے پاس آئیں، جیسا کہ انہوں نے اسرائیل میں کی گئی تمام حماقتوں کے مطابق کیا۔\n11۔ یوں اسرائیل کے تمام لوگ شہر کے خلاف جمع ہو گئے، ایک آدمی کی طرح جڑے ہوئے۔ {بنت...: عبرانی۔ دوستو}\n12۔ اور اسرائیل کے قبائل نے بنیامین کے تمام قبیلے میں آدمی بھیجے اور کہا، یہ کون سی برائی ہے جو تم میں ہو رہی ہے؟\n13۔ اب ہم سب کو آزاد کرو، بیلیال کے بچوں کو، جو گبعیہ میں ہیں، تاکہ ہم انہیں قتل کر دیں اور اسرائیل سے برائی کو دور کر دیں۔ لیکن بنیامین کے بچوں نے اپنے بھائیوں، بنی اسرائیل کی آواز کو نہیں سنا:\n14۔ لیکن بنیامین کے بچے شہروں سے نکل کر گبعیہ پہنچے تاکہ بنی اسرائیل کے خلاف لڑ سکیں۔\n15۔ اور اس وقت بنیامین کے بیٹے شہروں میں سے چھبیس چھبیس ہزار آدمی تھے جو تلوار چلانے والے تھے، گبعیہ کے باشندوں کے علاوہ جو سات سو منتخب مرد تھے۔\n16۔ ان تمام لوگوں میں {وہاں} سات سو منتخب مرد تھے جو بائیں ہاتھ تھے؛ ہر کوئی پتھر تھوڑے سے موڑ پر پھینک سکتا تھا، اور چوک بھی نہیں سکتا تھا۔\n17۔ اور بنی امین کے علاوہ اسرائیل کے مردوں کی تعداد چار لاکھ تھی جو تلوار نکال رہے تھے: یہ سب جنگی لوگ تھے۔\n18۔ اور بنی اسرائیل اٹھے، خدا کے گھر گئے، خدا سے مشورہ مانگا اور کہا، ہم میں سے کون پہلے بنیامین کے بچوں کے خلاف جنگ میں جائے گا؟ اور خداوند نے فرمایا، یہوداہ سب سے پہلے اوپر جائے گا۔\n19۔ اور بنی اسرائیل صبح اٹھے اور گبعیہ کے خلاف خیمہ زن ہو گئے۔\n20۔ اور بنی اسرائیل کے لوگ بنیامین کے خلاف لڑنے نکلے؛ اور اسرائیل کے لوگ گبعیہ میں ان کے خلاف لڑنے کے لیے صف بندی میں کھڑے ہو گئے۔\n21۔ اور بنیامین کے بچے گبعیہ سے باہر نکلے اور اس دن بنی اسرائیل کے بیس ہزار آدمیوں کو تباہ کر دیا۔\n22۔ اور بنی اسرائیل کے لوگوں نے خود کو حوصلہ دیا، اور اپنی جنگ دوبارہ اس جگہ ترتیب دی جہاں انہوں نے پہلے دن خود کو صف بندی میں کھڑا کیا۔\n23۔ (اور بنی اسرائیل اوپر گئے اور خداوند کے سامنے رونے لگے، یہاں تک کہ شام تک اور خداوند سے مشورہ مانگا کہ کیا میں دوبارہ اوپر جا کر اپنے بھائی بنیامین کے بچوں کے خلاف لڑوں؟ اور خداوند نے فرمایا، اس کے خلاف جاؤ۔)\n24۔ اور بنی اسرائیل دوسرے دن بنیامین کے بچوں کے خلاف قریب آ گئے۔\n25۔ اور بنیامین دوسرے دن گبعیہ سے ان کے خلاف نکلا، اور بنی اسرائیل کے اٹھارہ ہزار آدمیوں کو دوبارہ زمین پر گرا دیا؛ ان سب نے تلوار نکالی۔\n26۔ پھر تمام بنی اسرائیل اور تمام لوگ اوپر چلے گئے، خدا کے گھر آئے، روئے، اور خداوند کے سامنے بیٹھ گئے، اور اس دن صبح تک روزہ رکھا، اور خداوند کے سامنے سلائی اور صلح کی قربانیاں پیش کیں۔\n27۔ اور بنی اسرائیل نے خداوند سے پوچھا، (کیونکہ خدا کے عہد کا صندوق ان دنوں وہاں تھا،\n28۔ اور فینحاس، جو الیعزر کا بیٹا تھا، ہارون کا بیٹا، ان دنوں اس کے سامنے کھڑا تھا،) اور کہا، کیا میں پھر سے اپنے بھائی بنیامین کے بچوں کے خلاف جنگ کے لیے جاؤں یا رک جاؤں؟ اور خداوند نے فرمایا، اوپر جاؤ؛ کیونکہ کل میں انہیں تمہارے ہاتھ میں دے دوں گا۔\n29۔ اور اسرائیل نے گبعیہ کے آس پاس جھوٹے لوگوں کو لگا دیا۔\n30۔ اور تیسرے دن بنی اسرائیل نے بنیامین کے بچوں کے خلاف کھڑے ہو کر گبعہ کے خلاف صف بندی کی، جیسا کہ دیگر اوقات میں ہوا۔\n31۔ اور بنیامین کے بچے لوگوں کے خلاف نکلے، {اور} شہر سے دور ہو گئے؛ اور انہوں نے لوگوں کو مارنا شروع کیا، {اور} دیگر اوقات کی طرح شاہراہوں پر قتل کیا، جن میں سے ایک خدا کے گھر تک جاتا ہے اور دوسرا میدان میں گبعہ کو، تقریبا تیس اسرائیلی آدمیوں کو۔ {مارنے کے لیے...: عبرانی۔ زخمیوں کو مارنے کے لیے، وغیرہ} {گھر...: یا، بیت ھل}\n32۔ اور بنیامین کے بچوں نے کہا، وہ ہمارے سامنے بھی محبت میں مبتلا ہیں، جیسے پہلی بار ہوا تھا۔ لیکن بنی اسرائیل نے کہا، آؤ بھاگ جائیں، اور انہیں شہر سے شاہراہوں کی طرف لے جائیں۔\n33۔ اور اسرائیل کے تمام لوگ اپنی جگہ سے اٹھ کھڑے ہوئے اور بعلتمار میں صف بندی میں کھڑے ہو گئے: اور اسرائیل کے جھوٹے لوگ اپنی جگہوں سے نکل آئے، حتیٰ کہ گبعہ کے چراگاہوں سے بھی۔\n34۔ اور پورے اسرائیل میں سے دس ہزار منتخب مرد گبعیاہ کے خلاف آئے، اور جنگ شدید تھی: لیکن وہ نہیں جانتے تھے کہ ان کے قریب برائی ہے۔\n35۔ اور خداوند نے اسرائیل کے سامنے بنیامین کو مارا: اور بنی اسرائیل نے اس دن بنیمی بیس پچیس ہزار سو آدمیوں کو تباہ کر دیا: یہ سب تلوار نکالے۔\n36۔ تو بنیامین کے بچوں نے دیکھا کہ وہ محبت میں مبتلا ہو گئے ہیں: کیونکہ بنی اسرائیل کے لوگوں نے بنیمی لوگوں کو جگہ دی، کیونکہ انہوں نے ان جھوٹے لوگوں پر بھروسہ کیا جو انہوں نے گبعہ کے پاس رکھے تھے۔\n37۔ اور جھوٹے لوگ جلدی سے گبعہ پر حملہ آور ہوئے؛ اور جھوٹ بولنے والے خود بھی ساتھ آئے، اور پورے شہر کو تلوار کی دھار سے مارا۔ {ڈریو...: یا، ترمپٹ کے ساتھ لمبی آواز نکالی}\n38۔ اب اسرائیل کے مردوں اور جھوٹے انتظار کرنے والوں کے درمیان ایک مقررہ نشان تھا کہ وہ شہر سے دھوئیں کے ساتھ ایک بڑا شعلہ اٹھائیں۔ {اشارہ: یا، وقت} {اور: عبرانی۔ جس کے ساتھ} {شعلہ: عبرانی۔ بلندی}\n39۔ اور جب بنی اسرائیل کے لوگ جنگ میں پیچھے ہٹے، تو بنیامین نے تقریبا تیس لوگوں کو مارنا شروع کیا: کیونکہ انہوں نے کہا، یقینا وہ ہمارے سامنے مارا گیا ہے، جیسے پہلی جنگ میں۔ {مارنے کے لیے...: عبرانی۔ زخمیوں کو مارنے کے لیے}\n40۔ لیکن جب شعلہ شہر سے دھوئیں کے ستون کے ساتھ اٹھنے لگا، تو بنیمی لوگوں نے پیچھے دیکھا، اور دیکھو، شہر کی آگ آسمان کی طرف بلند ہو گئی۔ {دی فلیم: ہیب۔ پورا استعمال}\n41۔ اور جب بنی اسرائیل کے لوگ دوبارہ مڑے، تو بنیامین کے لوگ حیران رہ گئے، کیونکہ انہوں نے دیکھا کہ ان پر برائی آ گئی ہے۔ {آیا تھا...: عبرانی۔ انہیں چھوا تھا}\n42۔ اس لیے وہ اسرائیل کے لوگوں کے سامنے منہ موڑ کر بیابان کے راستے پر چلے گئے؛ لیکن لڑائی نے انہیں گھیر لیا؛ اور وہ جو ان شہروں سے نکلے جنہیں انہوں نے ان کے درمیان تباہ کیا۔\n43۔ {یوں} انہوں نے بنیمی لوگوں کو گھیر لیا، {اور} ان کا پیچھا کیا، {اور} آسانی سے انہیں سورج نکلنے کی طرف گبعیاہ کے خلاف روندا۔ {آسانی سے...: یا، مینوخہ سے، وغیرہ} {اوور...: عبرانی۔ اوور اگینسٹ}\n44۔ اور بنیامین کے اٹھارہ ہزار آدمی مارے گئے؛ یہ سب بہادر لوگ تھے۔\n45۔ اور وہ مڑے اور جنگل کی طرف ریمون کی چٹان کی طرف بھاگے: اور انہوں نے شاہراہوں پر ان کے بارے میں پانچ ہزار آدمی دیکھے؛ اور ان کا پیچھا سختی سے گدوم تک کیا، اور ان میں سے دو ہزار آدمیوں کو مار ڈالا۔\n46۔ تو اس دن بنیامین کے دن جو بھی مارا گیا، وہ صرف پچیس ہزار آدمی تھے جنہوں نے تلوار نکالی؛ یہ سب بہادر لوگ تھے۔\n47۔ لیکن چھ سو آدمیوں نے مڑ کر صحرا کی طرف بھاگ کر چٹان رمون کی طرف بھاگ گئے، اور چار ماہ تک چٹان ریمون میں قیام کیا۔\n48۔ اور بنی اسرائیل کے لوگوں نے دوبارہ بنیامین کے بچوں پر حملہ کیا، اور انہیں تلوار کی نوک سے مارا، اور ہر شہر کے لوگوں کو، جانور کی طرح، اور جو کچھ بھی ہاتھوں میں آیا، اور انہوں نے ان تمام شہروں کو آگ لگا دی جہاں وہ آئے۔ {ہاتھ میں آیا: عبرانی۔ مل گئی} {وہ آئے...: عبرانی۔ مل گئے}","1۔ اب بنی اسرائیل کے لوگوں نے مزپے میں قسم کھائی تھی اور کہا تھا، ہم میں سے کوئی بھی اپنی بیٹی کو بنیامین کے حوالے نہیں کرے گا۔\n2۔ اور لوگ خدا کے گھر آئے، اور وہاں خدا کے سامنے تک رہے، اپنی آوازیں بلند کیں اور رونے لگے؛\n3۔ اور کہا، اے خداوند اسرائیل کے خدا، یہ سب اسرائیل میں کیوں ہوا، کہ آج تک اسرائیل میں ایک قبیلہ غائب ہو؟\n4۔ اور کل ایسا ہوا کہ لوگ جلدی اٹھے، وہاں ایک قربان گاہ بنائی، اور جلانے کی قربانیاں اور صلح کی قربانیاں پیش کیں۔\n5۔ اور بنی اسرائیل نے کہا، اسرائیل کے تمام قبائل میں سے کون ہے جو خدا کی جماعت کے ساتھ نہیں آیا؟ کیونکہ انہوں نے اس کے بارے میں ایک بڑی قسم کھائی تھی جو خداوند کے پاس نہیں آیا، مزپیہ کے لیے، کہ اسے ضرور قتل کیا جائے گا۔\n6۔ اور بنی اسرائیل نے اپنے بھائی بنیامین کے لیے توبہ کی اور کہا، آج اسرائیل سے ایک قبیلہ کٹ گیا ہے۔\n7. ہم ان بیویوں کے لیے کیا کریں جو باقی رہ گئی ہیں، جب ہم نے خدا کے نام سے قسم کھائی ہے کہ ہم اپنی بیٹیوں میں سے انہیں بیویوں کو نہیں دیں گے؟\n8۔ اور انہوں نے کہا، اسرائیل کی قبائل میں سے کون سی ہے جو مزپیہ تک خداوند کے پاس نہیں آئی؟ اور دیکھو، جابشگلعاد سے کوئی بھی کیمپ میں نہیں آیا۔\n9۔ کیونکہ لوگ گنے جا چکے تھے، اور دیکھو، وہاں جابشجلعاد کے باشندے نہیں تھے۔\n10۔ اور جماعت نے وہاں بارہ ہزار بہادر مرد بھیجے اور انہیں حکم دیا، کہا کہ جبشگلیڈ کے باشندوں کو تلوار کی نوک سے، عورتوں اور بچوں سے مارو۔\n11۔ اور یہی وہ کام ہے جو تم کرو گے، تم ہر مرد اور ہر عورت کو مکمل طور پر تباہ کر دو گے جو مرد کے ہاتھوں سو چکی ہو۔ {نے لیا...: عبرانی۔ انسان کے ساتھ جھوٹ بولنے کو جانتا ہے}\n12۔ اور انہوں نے جابشگلعاد کے باشندوں میں چار سو نوجوان کنواریوں کو پایا جو کسی مرد کے ساتھ لیٹ کر کسی کو نہیں جانتی تھیں، اور انہیں شیلوہ کے کیمپ میں لے گئے، جو کنعان کی سرزمین میں ہے۔ {نوجوان...: عبرانی۔ نوجوان خواتین کنواری}\n13۔ اور پوری جماعت نے {کچھ} کو بھیجا کہ وہ بنیامین کے بچوں سے بات کریں جو چٹان رمون میں تھے، اور انہیں امن سے پکاریں۔ {بولنے کے لیے...: عببرانی۔ اور بولے اور پکارا} {پکارو...: یا، امن کا اعلان کرو}\n14۔ اور اسی وقت بنیامین دوبارہ آیا؛ اور انہوں نے انہیں وہ بیویاں دیں جنہیں انہوں نے جابشگلعاد کی عورتوں سے زندہ بچایا تھا: اور پھر بھی وہ کافی نہیں تھیں۔\n15۔ اور لوگوں نے بنیامین کے لیے توبہ کی، کیونکہ خداوند نے اسرائیل کے قبائل میں اختلاف پیدا کیا تھا۔\n16۔ پھر جماعت کے بزرگوں نے کہا، ہم ان بیویوں کے لیے کیا کریں جو باقی رہ گئی ہیں، جب کہ عورتیں بنیامین سے تباہ ہو رہی ہیں؟\n17۔ اور انہوں نے کہا، {جو لوگ بنیامین سے بچ نکلے ہیں} ان کے لیے وراثت ہونی چاہیے، کہ کوئی قبیلہ اسرائیل سے ختم نہ ہو۔\n18. اگرچہ ہم انہیں اپنی بیٹیوں کی بیویاں نہیں دے سکتے: کیونکہ بنی اسرائیل نے قسم کھائی ہے کہ جو بنیامین کو بیوی دیتا ہے وہ لعنتی ہو۔\n19۔ پھر انہوں نے کہا، دیکھو، {دیکھو} خداوند کی عید ہر سال شیلوہ میں {ایک جگہ} میں {ہے} جو {ہے} بیت ایل کے شمالی کنارے، بیت ایل سے شیکم جانے والی شاہراہ کے مشرقی کنارے، اور لبونا کے جنوب میں۔ {سالانہ: عبرانی۔ سال بہ سال} {مشرق میں...: یا، طلوع آفتاب کی طرف} {ہائی وے پر: یا، ہائی وے پر}\n20۔ اسی لیے انہوں نے بنیامین کے بچوں کو حکم دیا، کہہ دیا، جاؤ اور انگور کے باغات میں انتظار کرو؛\n21۔ اور دیکھو، اور دیکھو، اگر شیلوہ کی بیٹیاں رقص کے لیے باہر آئیں، تو تم انگور کے باغات سے نکل آؤ، اور ہر مرد کو اس کی بیوی کو پکڑو، اور بنیامین کی زمین جاؤ۔\n22۔ اور جب ان کے باپ یا بھائی ہمارے پاس شکایت کرنے آئیں گے، تو ہم انہیں کہیں گے، ہمارے لیے ان کے ساتھ مہربان رہو: کیونکہ ہم نے جنگ میں ہر آدمی کی بیوی کو محفوظ نہیں رکھا: کیونکہ تم نے اس وقت انہیں نہیں دیا، تاکہ تم قصوروار ہو۔ {مہربان رہو...: یا، ہمیں ان میں خوش کرو}\n23۔ اور بنیامین کے بچوں نے ایسا ہی کیا، اور ان میں سے ان کی تعداد کے مطابق بیویاں لیں جو رقص کرتی تھیں، جنہیں انہوں نے پکڑ لیا، اور وہ اپنی میراث میں واپس چلے گئے، شہروں کی مرمت کی، اور وہاں بسے۔\n24۔ اور اس وقت اسرائیل کے بچے وہاں سے روانہ ہوئے، ہر آدمی اپنے قبیلے اور اپنے خاندان کے پاس، اور وہاں سے ہر آدمی اپنی میراث کے لیے روانہ ہوئے۔\n25۔ ان دنوں اسرائیل میں کوئی بادشاہ نہیں تھا: ہر انسان اپنی آنکھوں میں صحیح عمل کرتا تھا۔"];
